async function genCardNumber() {
    for (let i = 0; i < 30; i++) {
        const n = String(Math.floor(10000000 + Math.random() * 90000000));
        if (!(await Personnel.findOne({ cardNumber: n }, { _id: 1 }).lean())) return n;
    }
    return String(Date.now()).slice(-8);
}
async function ensureCardNumbers() {
    try {
        const cond = { $or: [{ cardNumber: null }, { cardNumber: "" }] };
        const missing = await Personnel.find(cond, { _id: 1 }).limit(1000).lean();
        for (const m of missing) {
            await Personnel.updateOne({ _id: m._id, ...cond }, { $set: { cardNumber: await genCardNumber() } });
        }
    } catch (e) { console.error("❌ فشل توليد أرقام البطاقات:", e.message); }
}

// نسخ القاعدة القديمة للجديدة (مرة وحدة): حط عنوان القديمة في OLD_MONGO_URI وعنوان الجديدة في MONGO_URI
// آمن للتكرار (ما يكتب فوق شي موجود). كولكشن imageblobs (من نظام الصور القديم المحذوف) ما ينسخ عشان ما ياكل المساحة.
async function copyOldMainDb() {
    const oldUri = (process.env.OLD_MONGO_URI || "").trim();
    if (!oldUri || oldUri === CONFIG.MONGO_URI) return;
    const dstDb = mongoose.connection.db;
    const mark = dstDb.collection("_migrations");
    if (await mark.findOne({ _id: "mainDbCopy" })) return;
    console.log("🔄 جاري نسخ القاعدة القديمة للقاعدة الجديدة...");
    const src = mongoose.createConnection(oldUri);
    src.on("error", () => {});
    const bsonSize = d => {
        try { return mongoose.mongo.BSON.calculateObjectSize(d); }
        catch (e) { return JSON.stringify(d).length; }
    };
    try {
        await src.asPromise();
        const cols = await src.db.listCollections({}, { nameOnly: true }).toArray();
        for (const { name } of cols) {
            if (name.startsWith("system.") || name === "_migrations" || name === "imageblobs") continue;
            const dst = dstDb.collection(name);
            const cur = src.db.collection(name).find({});
            let batch = [], bytes = 0, n = 0;
            const flush = async () => {
                if (!batch.length) return;
                await dst.bulkWrite(batch, { ordered: false });
                batch = []; bytes = 0;
            };
            let d;
            while ((d = await cur.next())) {
                const { _id, ...rest } = d;
                batch.push({ updateOne: { filter: { _id }, update: { $setOnInsert: rest }, upsert: true } });
                bytes += bsonSize(d); n++;
                if (batch.length >= 100 || bytes > 8 * 1024 * 1024) await flush();
            }
            await flush();
            console.log("   ✔ " + name + ": " + n + " مستند");
        }
        await mark.updateOne({ _id: "mainDbCopy" }, { $set: { at: new Date() } }, { upsert: true });
        console.log("✅ تم نسخ القاعدة القديمة بالكامل.");
    } finally {
        await src.close().catch(() => {});
    }
}

// الشرطة العسكرية صارت قطاع: كل عضو له قطاع واحد فقط (isMP = قطاعه mp)
async function migrateMpSector() {
    try {
        const toMp = await Account.find({ isMP: true, sector: { $ne: "mp" } }, { uid: 1, sector: 1 }).lean();
        for (const a of toMp) {
            if (a.sector) console.log("ℹ️ نقل للشرطة العسكرية (كان في قطاع " + a.sector + "):", a.uid);
            const p = await Personnel.findOne({ discord: a.uid }, { unit: 1 }).lean();
            const oldLabel = a.sector ? CONFIG.SECTORS[a.sector] : null;
            const upd = { sector: "mp" };
            if (p && (!p.unit || p.unit === "غير محدد" || (oldLabel && p.unit === oldLabel))) upd.unit = CONFIG.SECTORS.mp;
            await Account.updateOne({ uid: a.uid }, { $set: { sector: "mp", isMP: true } });
            await Personnel.updateOne({ discord: a.uid }, { $set: upd });
        }
        await Account.updateMany({ sector: "mp", isMP: { $ne: true } }, { $set: { isMP: true } });
        await Account.updateMany({ isMP: true, sector: { $ne: "mp" } }, { $set: { sector: "mp" } });
        if (toMp.length) console.log("✅ تم ربط الشرطة العسكرية بالقطاعات (" + toMp.length + " عضو)");
    } catch (e) { console.error("❌ فشل ترحيل الشرطة العسكرية:", e.message); }
}

async function ensureSectorFields() {
    try {
        const accs = await Account.find({ status: "approved" }, { uid: 1, sector: 1 }).lean();
        const bySector = {};
        for (const a of accs) { const k = a.sector || ""; (bySector[k] = bySector[k] || []).push(a.uid); }
        for (const [k, uids] of Object.entries(bySector)) {
            await Personnel.updateMany({ discord: { $in: uids }, sector: { $ne: k || null } }, { $set: { sector: k || null } });
        }
    } catch (e) { console.error("❌ فشل مزامنة القطاعات:", e.message); }
}

