// من يقدر يقبل/يرفض مخالفة من ديسكورد: الكبار / مسؤول المخالفات العام / قائد القطاع أو مسؤول مخالفات القطاع (قطاعه فقط، وبدون مخالفاته)
async function discordCanReviewViolation(interaction, v, settings) {
    const uid = interaction.user.id;
    if (isSeniorAdmin(uid) || interaction.memberPermissions?.has(PermissionFlagsBits.Administrator) || isViolationsOfficer(uid, settings)) return true;
    if (v.reporterDiscord === uid) return false;
    const sr = getSectorRole(uid, settings);
    const vo = getSectorViolOfficer(uid, settings);
    const isCmd = !!(sr && sr.role === "commander");
    const sector = isCmd ? sr.sector : (vo ? vo.sector : null);
    if (!sector) return false;
    const acc = await Account.findOne({ uid: v.reporterDiscord }, { sector: 1 }).lean();
    if (!acc || acc.sector !== sector) return false;
    if (!isCmd) { const sec = secLead(settings, sector) || {}; if (sec.commanderId && sec.commanderId === v.reporterDiscord) return false; }
    return true;
}

client.on("interactionCreate", async interaction => {
    try {
        if (interaction.isChatInputCommand()) {
            const { commandName } = interaction;

            if (commandName === "حظر") {
                if (!isBotAdmin(interaction.user.id)) {
                    return interaction.reply({ content: "🚫 هذا الأمر مخصص لكبار المسؤولين فقط.", ephemeral: true });
                }
                const target = interaction.options.getUser("اللاعب");
                const reason = interaction.options.getString("السبب");
                await Personnel.findOneAndUpdate(
                    { discord: target.id },
                    {
                        $set: { isBlocked: true },
                        $push: { notes: { text: `🚫 حظر من الموقع — السبب: ${reason}`, addedBy: interaction.user.id, addedByTag: interaction.user.username } },
                        $setOnInsert: { discordTag: target.username },
                    },
                    { upsert: true }
                );
                await logEvent({ action: "حظر عسكري (أمر)", discordId: target.id, discordTag: target.username, actorId: interaction.user.id, actorTag: interaction.user.username, details: `السبب: ${reason}` });
                return interaction.reply({ content: `🚫 تم حظر <@${target.id}> من الموقع.\n📝 السبب: ${reason}`, ephemeral: true });
            }

            if (commandName === "فك-حظر") {
                if (!isBotAdmin(interaction.user.id)) {
                    return interaction.reply({ content: "🚫 هذا الأمر مخصص لكبار المسؤولين فقط.", ephemeral: true });
                }
                const target = interaction.options.getUser("اللاعب");
                const p = await Personnel.findOneAndUpdate({ discord: target.id }, { isBlocked: false }, { new: true });
                if (!p) return interaction.reply({ content: "❌ هذا اللاعب غير مسجل بالنظام أصلاً.", ephemeral: true });
                await logEvent({ action: "فك حظر عسكري (أمر)", discordId: target.id, discordTag: target.username, actorId: interaction.user.id, actorTag: interaction.user.username });
                return interaction.reply({ content: `✅ تم فك حظر <@${target.id}> من الموقع.`, ephemeral: true });
            }
            return;
        }

        if (interaction.isButton()) {
            const id = interaction.customId;

            if (id.startsWith("approve_") || id.startsWith("reject_")) {
                const sep = id.indexOf("_");
                const action = id.slice(0, sep), vid = id.slice(sep + 1);
                const isApprove = action === "approve";
                // أول شي نرد على ديسكورد (عنده 3 ثواني بس)، وبعدها نسوي الفحوصات والاستعلامات
                if (!isApprove) {
                    const modal = new ModalBuilder().setCustomId(`rejectmodal_${vid}`).setTitle("سبب الرفض");
                    const input = new TextInputBuilder()
                        .setCustomId("reason").setLabel("اكتب سبب رفض المخالفة")
                        .setStyle(TextInputStyle.Paragraph).setRequired(true).setMaxLength(500);
                    modal.addComponents(new ActionRowBuilder().addComponents(input));
                    return interaction.showModal(modal);
                }
                await interaction.deferReply({ ephemeral: true });
                const settings = await getSettings();
                const v = await Violation.findById(vid).catch(() => null);
                if (!v || v.status !== "pending") return interaction.editReply({ content: "هذه المخالفة تمت مراجعتها مسبقاً." });
                if (!(await discordCanReviewViolation(interaction, v, settings))) return interaction.editReply({ content: "🚫 ما تملك صلاحية." });
                const ar = await approveViolation(v, interaction.user.id, interaction.user.username);
                if (ar && ar.blocked) return interaction.editReply({ content: ar.unassigned ? "🚫 حساب مقدّم المخالفة بدون رتبة أو قطاع، ما تنقبل مخالفاته." : ar.investigation ? "🔒 هذا العسكري تحت التحقيق السيبراني، ما تنقبل مخالفاته حالياً." : "🚨 على هذا العسكري استدعاء نشط، ما تنقبل مخالفاته حتى ينتهي الاستدعاء." });
                return interaction.editReply({ content: "✅ تم قبول المخالفة." });
            }

            if (id.startsWith("leave_")) {
                const parts = id.split("_");
                await interaction.deferUpdate();
                const out = await decideLeaveRequest(parts[2], interaction.user.id, interaction.user.username, parts[1] === "ok" ? "approve" : "reject", interaction.member);
                if (out.error) return interaction.followUp({ content: "🚫 " + out.error, ephemeral: true });
                return;
            }

            if (id.startsWith("mppr_")) {
                const parts = id.split("_");
                await interaction.deferUpdate();
                const out = await decideMPPointsRequest(parts[2], interaction.user.id, interaction.user.username, parts[1] === "ok" ? "approve" : "reject", "discord");
                if (out.error) return interaction.followUp({ content: "🚫 " + out.error, ephemeral: true });
                return;
            }

            return;
        }

        if (interaction.isModalSubmit()) {
            if (interaction.customId.startsWith("rejectmodal_")) {
                await interaction.deferReply({ ephemeral: true });
                const vid = interaction.customId.split("_")[1];
                const reason = interaction.fields.getTextInputValue("reason");
                const v = await Violation.findById(vid).catch(() => null);
                if (!v || v.status !== "pending") return interaction.editReply({ content: "هذه المخالفة تمت مراجعتها مسبقاً." });
                const settings = await getSettings();
                if (!(await discordCanReviewViolation(interaction, v, settings))) return interaction.editReply({ content: "🚫 ما تملك صلاحية." });
                const rr = await rejectViolation(v, interaction.user.id, interaction.user.username, reason);
                if (rr && rr.blocked) return interaction.editReply({ content: rr.investigation ? "🔒 هذا العسكري تحت التحقيق السيبراني، ما تنرفض مخالفاته حالياً." : "🚨 على هذا العسكري استدعاء نشط، ما تنرفض مخالفاته حالياً." });
                return interaction.editReply({ content: "✅ تم رفض المخالفة وحفظ السبب." });
            }
        }
    } catch (e) {
        console.error("❌ خطأ بالتفاعل:", e);
        // ما نخلي الزر يعلق: نرد بالخطأ بدل ما يبقى "يفكر"
        try {
            const msg = "⚠️ صار خطأ أثناء التنفيذ، حاول مرة ثانية.";
            if (interaction.deferred || interaction.replied) await interaction.editReply({ content: msg });
            else if (interaction.isRepliable && interaction.isRepliable()) await interaction.reply({ content: msg, ephemeral: true });
        } catch (e2) {}
    }
});

const activeVehicleSessions = new Set();
client.on("messageCreate", async message => {
    if (message.author.bot) return;
    if (!message.content.startsWith("-")) return;
    const [cmd] = message.content.slice(1).trim().split(/\s+/);
    if (cmd !== "مركبات") return;

    const senior = isBotAdmin(message.author.id);
    if (!senior) return;
    if (activeVehicleSessions.has(message.author.id)) {
        return message.reply("عندك جلسة إضافة مركبات شغالة حالياً، أكملها أول.");
    }
    activeVehicleSessions.add(message.author.id);
    const filter = m => m.author.id === message.author.id;
    try {
        await message.reply(`كم عدد المركبات اللي تبي تضيفها؟ (الأقصى ${CONFIG.MAX_VEHICLES_ADD})`);
        const countCollected = await message.channel.awaitMessages({ filter, max: 1, time: 60000, errors: ["time"] });
        const countMsg = countCollected.first();
        const count = parseInt(countMsg.content.trim());
        if (isNaN(count) || count < 1 || count > CONFIG.MAX_VEHICLES_ADD) {
            activeVehicleSessions.delete(message.author.id);
            return message.reply(`❌ الرقم غير صحيح. لازم يكون بين 1 و ${CONFIG.MAX_VEHICLES_ADD}.`);
        }
        countMsg.delete().catch(() => {});
        const added = [];
        for (let i = 1; i <= count; i++) {
            const p = await message.channel.send(`🚗 اكتب اسم المركبة رقم ${i} من ${count} (يمديك ترفق صورة مع الرسالة):`);
            const collected = await message.channel.awaitMessages({ filter, max: 1, time: 60000, errors: ["time"] });
            const nameMsg = collected.first();
            const name = nameMsg.content.trim();
            const photo = nameMsg.attachments.first()?.url || null;
            nameMsg.delete().catch(() => {});
            p.delete().catch(() => {});
            if (!name) { i--; continue; }
            try {
                await Vehicle.create({ name, photo, addedBy: message.author.id });
                added.push(name);
            } catch (e) {
                await message.channel.send(`⚠️ المركبة "${name}" موجودة مسبقاً، تم تجاوزها.`);
            }
        }
        await message.channel.send(`✅ تم إضافة ${added.length} مركبة:\n${added.map(n => `• ${n}`).join("\n") || "لا شيء"}`);
    } catch (e) {
        await message.channel.send("⏱️ انتهى الوقت، تم إلغاء العملية.");
    } finally {
        activeVehicleSessions.delete(message.author.id);
    }
});

