const APP_VER = (() => { try { return crypto.createHash("md5").update(require("fs").readFileSync(__filename)).digest("hex").slice(0, 12); } catch (e) { return String(Date.now()); } })();
const app = express();

["get", "post", "put", "delete", "patch"].forEach(method => {
    const original = app[method].bind(app);
    app[method] = (path, ...handlers) => {
        const wrapped = handlers.map(h => {
            if (typeof h !== "function") return h;
            return (req, res, next) => {
                Promise.resolve(h(req, res, next)).catch(err => {
                    console.error(`❌ خطأ في ${method.toUpperCase()} ${path}:`, err);
                    if (!res.headersSent) res.status(500).json({ error: "خطأ: " + (err && err.message ? err.message : "غير معروف"), ok: false });
                });
            };
        });
        return original(path, ...wrapped);
    };
});

