const photoUrlCache = new Map();
const PHOTO_CACHE_MS = 20 * 60 * 60 * 1000;
function withTimeout(promise, ms) {
    return Promise.race([
        promise,
        new Promise((_, reject) => setTimeout(() => reject(new Error("timeout")), ms)),
    ]);
}
app.get("/api/violations/:id/photo", ensureAuth, async (req, res) => {
    try {
        const v = await Violation.findById(req.params.id).select("photo photoDb photoChannelId photoMessageId reporterDiscord");
        if (!v) return res.status(404).json({ error: "المخالفة غير موجودة" });
        const settings = await getSettings();
        const allowed = v.reporterDiscord === req.user.id || isSeniorAdmin(req.user.id)
            || settings.adminList.includes(req.user.id)
            || !!getSectorRole(req.user.id, settings) || !!getPersonnelOfficerSector(req.user.id, settings)
            || !!getSectorViolOfficer(req.user.id, settings)
            || isViolationsOfficer(req.user.id, settings) || isHighCommand(req.user.id, settings);
        if (!allowed) return res.status(403).json({ error: "غير مصرح" });
        { const d = await violationPhotoDoc(v); if (d && d.full) return res.json({ photo: d.full }); }

        if (v.photoChannelId && v.photoMessageId) {
            const cacheKey = v._id.toString();
            const cached = photoUrlCache.get(cacheKey);
            if (cached && (Date.now() - cached.fetchedAt) < PHOTO_CACHE_MS) {
                return res.json({ photo: cached.url });
            }
            try {
                const channel = client.channels.cache.get(v.photoChannelId) || await withTimeout(client.channels.fetch(v.photoChannelId), 10000);
                const msg = await withTimeout(channel.messages.fetch(v.photoMessageId), 10000);
                const att = msg.attachments.first();
                if (att) {
                    photoUrlCache.set(cacheKey, { url: att.url, fetchedAt: Date.now() });
                    return res.json({ photo: att.url });
                }
            } catch (e) {
                console.error("❌ فشل جلب صورة المخالفة من ديسكورد:", e.message);
                if (!v.photo) return res.status(503).json({ error: "تعذر جلب الصورة من ديسكورد حالياً، حاول مرة ثانية بعد شوي" });
            }
        }
        res.json({ photo: v.photo || null });
    } catch (e) {
        console.error("❌ فشل تحميل صورة المخالفة:", e);
        res.status(500).json({ error: "تعذر تحميل الصورة" });
    }
});

// ── الصورة كملف مباشر: السيرفر يجيبها من ديسكورد ويرسلها (بدون ما المتصفح يعلق على رابط ديسكورد) ──
const photoBufCache = new Map();
const PHOTO_BUF_MAX = 40;
function photoBufPut(key, val) {
    photoBufCache.set(key, val);
    while (photoBufCache.size > PHOTO_BUF_MAX) photoBufCache.delete(photoBufCache.keys().next().value);
}
async function fetchDiscordAttachmentBuf(channelId, messageId, cacheKey) {
    const hit = photoBufCache.get(cacheKey);
    if (hit && (Date.now() - hit.at) < 30 * 60 * 1000) return hit;
    const channel = client.channels.cache.get(channelId) || await withTimeout(client.channels.fetch(channelId), 6000);
    const msg = await withTimeout(channel.messages.fetch(messageId), 6000);
    const att = msg.attachments.first();
    if (!att) return null;
    photoUrlCache.set(cacheKey, { url: att.url, fetchedAt: Date.now() });
    const r = await fetch(att.url, { signal: AbortSignal.timeout(9000) });
    if (!r.ok) throw new Error("HTTP " + r.status);
    const buf = Buffer.from(await r.arrayBuffer());
    const val = { buf, type: att.contentType || r.headers.get("content-type") || "image/jpeg", at: Date.now() };
    photoBufPut(cacheKey, val);
    return val;
}
function sendPhotoBuf(res, val) {
    res.set("Content-Type", val.type || "image/jpeg");
    res.set("Cache-Control", "private, max-age=600");
    res.send(val.buf);
}
async function violationPhotoAllowed(req, v) {
    const settings = await getSettings();
    return v.reporterDiscord === req.user.id || isSeniorAdmin(req.user.id)
        || settings.adminList.includes(req.user.id)
        || !!getSectorRole(req.user.id, settings) || !!getPersonnelOfficerSector(req.user.id, settings)
        || !!getSectorViolOfficer(req.user.id, settings)
        || isViolationsOfficer(req.user.id, settings) || isHighCommand(req.user.id, settings);
}
async function violationPhotoDoc(v) {
    if (!(v && v.photoDb && ViolationPhoto)) return null;
    try { return await ViolationPhoto.findOne({ violationId: String(v._id) }).lean(); } catch (e) { return null; }
}
function sendDataUrl(res, dataUrl) {
    const m = /^data:(image\/[a-z+]+);base64,(.+)$/s.exec(String(dataUrl || ""));
    if (!m) return false;
    sendPhotoBuf(res, { buf: Buffer.from(m[2], "base64"), type: m[1] });
    return true;
}
app.get("/api/violations/:id/thumb", ensureAuth, async (req, res) => {
    try {
        const v = await Violation.findById(req.params.id).select("photoDb reporterDiscord").lean();
        if (!v) return res.status(404).send("not found");
        if (!(await violationPhotoAllowed(req, v))) return res.status(403).send("forbidden");
        const d = await violationPhotoDoc(v);
        if (d && sendDataUrl(res, d.thumb || d.full)) return;
        return res.redirect(302, "/api/violations/" + encodeURIComponent(req.params.id) + "/photo-file");
    } catch (e) { res.status(500).send("error"); }
});
app.get("/api/violations/:id/photo-file", ensureAuth, async (req, res) => {
    try {
        const v = await Violation.findById(req.params.id).select("photo photoDb photoChannelId photoMessageId reporterDiscord").lean();
        if (!v) return res.status(404).send("not found");
        const settings = await getSettings();
        const allowed = v.reporterDiscord === req.user.id || isSeniorAdmin(req.user.id)
            || settings.adminList.includes(req.user.id)
            || !!getSectorRole(req.user.id, settings) || !!getPersonnelOfficerSector(req.user.id, settings)
            || !!getSectorViolOfficer(req.user.id, settings)
            || isViolationsOfficer(req.user.id, settings) || isHighCommand(req.user.id, settings);
        if (!allowed) return res.status(403).send("forbidden");
        { const d = await violationPhotoDoc(v); if (d && sendDataUrl(res, d.full)) return; }
        if (v.photoChannelId && v.photoMessageId) {
            const ck = "v:" + v._id;
            try {
                const val = await fetchDiscordAttachmentBuf(v.photoChannelId, v.photoMessageId, ck);
                if (val) return sendPhotoBuf(res, val);
            } catch (e) {
                console.error("❌ فشل جلب صورة المخالفة (ملف):", e.message);
                const u = photoUrlCache.get(ck);
                if (u && u.url && !v.photo) return res.redirect(302, u.url);
            }
        }
        if (v.photo && v.photo.startsWith("data:image")) {
            const m = /^data:(image\/[a-z+]+);base64,(.+)$/s.exec(v.photo);
            if (m) return sendPhotoBuf(res, { buf: Buffer.from(m[2], "base64"), type: m[1] });
        }
        res.status(404).send("no photo");
    } catch (e) {
        console.error("❌ photo-file:", e.message);
        res.status(500).send("error");
    }
});

