const OFF_ROOMS_MAX = 5;
// ---------- المدربين + روم التدريب (901 فقط) ----------
const OFF_TRAIN_ROOMS = [901];
function offIsTrain(n) { return OFF_TRAIN_ROOMS.includes(n); }
// رومات التحقيق السيبراني الصوتية (500..899)
function offIsCyber(n) { return Number.isInteger(n) && n >= 500 && n <= 899; }
async function offIsTrainer(uid) {
    const st = await getSettings();
    return Array.isArray(st.officerTrainers) && st.officerTrainers.includes(String(uid));
}
async function ensureTrainerOrSenior(req, res, next) {
    if (!req.isAuthenticated()) return res.status(401).json({ error: "غير مسجّل دخول" });
    if (isSeniorAdmin(req.user.id)) return next();
    if (await offIsTrainer(req.user.id)) return next();
    return res.status(403).json({ error: "هذا القسم للمدربين وكبار المسؤولين فقط" });
}
async function ensureRecAccess(req, res, next) {
    if (!req.isAuthenticated()) return res.status(401).json({ error: "غير مسجّل دخول" });
    if (isSeniorAdmin(req.user.id)) return next();
    if (await offIsTrainer(req.user.id)) return next();
    if ((await courtRole(req.user.id)).staff) return next();
    return res.status(403).json({ error: "غير مصرح" });
}
const offRecActive = new Map();
function offRecEnd(n, graceful) {
    const r = offRecActive.get(n);
    if (!r) return;
    offRecActive.delete(n);
    OfficerRec.updateOne({ sid: r.sid, endedAt: null }, { $set: { endedAt: graceful ? new Date() : new Date(r.lastAt) } }).catch(() => {});
}
function offRecIsActive(n) {
    const r = offRecActive.get(n);
    if (!r) return false;
    const m = offLive.get(n);
    if (!m || !m.has(r.uid) || Date.now() - r.lastAt > 45000) { offRecEnd(n, false); return false; }
    return true;
}
async function offRecCleanup() {
    try {
        const old = await OfficerRec.find({ $or: [
            { n: { $not: { $gte: 950, $lte: 979 } }, startedAt: { $lt: new Date(Date.now() - 14 * 24 * 3600 * 1000) } },
            { n: { $gte: 950, $lte: 979 }, startedAt: { $lt: new Date(Date.now() - 30 * 24 * 3600 * 1000) } },
        ] }).select("sid").lean();
        if (!old.length) return;
        const sids = old.map(r => r.sid);
        await OfficerRecChunk.deleteMany({ sid: { $in: sids } });
        await OfficerRec.deleteMany({ sid: { $in: sids } });
    } catch (e) {}
}
setTimeout(offRecCleanup, 60000);
setInterval(offRecCleanup, 6 * 3600 * 1000);
const offLive = new Map();   // n -> Map(uid -> { uid, name, isSenior, joinedAt })
const offDeaf = new Map();   // n -> Set(uid) اللي عليهم ديفن
const courtKindByN = new Map(); // رقم الروم -> "court" | "inv"
// ---------- أسئلة المقابلة (5 أسئلة تظهر للكبار فقط، والكبير يعرضها للمتقدم ويقيّمها صح/غلط) ----------
const OFFICER_INTERVIEW_QUESTIONS = [
    "تم إصدار أمر لك من قائد أعلى رتبة، لكنك ترى أن الأمر سيؤثر سلبًا على القطاع، كيف تتصرف؟",
    "أثناء قيادتك لمهمة، اكتشفت أن أحد الضباط تحت قيادتك ارتكب مخالفة جسيمة، كيف تتعامل معه دون التأثير على سير المهمة؟",
    "في حال تعارضت أوامر ضابطين أعلى منك رتبة، وكلٌ منهما يطلب منك تنفيذ أمر مختلف، كيف تحدد الأمر الذي ستنفذه؟",
    "تم تعيينك مسؤولًا عن قطاع يعاني من الفوضى وضعف الانضباط، ما أول قراراتك؟ وكيف تعيد فرض النظام؟",
    "إذا اكتشفت أن ضابطًا قريبًا منك يستغل صلاحياته لتحقيق مصلحة شخصية، هل تتخذ إجراءً بحقه رغم علاقتك به؟ وضّح تصرفك",
];
const offIv = new Map();     // n -> Map(uid -> { cur: null|0..4, marks: ["","","","",""] })  ("r" صح, "w" غلط)
const offChat = new Map();   // n -> { seq, msgs: [] }
const OFF_CHAT_MAX = 100;
function offIvClean(marks) {
    const out = ["", "", "", "", ""];
    if (Array.isArray(marks)) for (let i = 0; i < 5; i++) out[i] = (marks[i] === "r" || marks[i] === "w") ? marks[i] : "";
    return out;
}
function offIvGet(n, uid) {
    let m = offIv.get(n);
    if (!m) { m = new Map(); offIv.set(n, m); }
    let e = m.get(uid);
    if (!e) { e = { cur: null, marks: offIvClean(null), report: null }; m.set(uid, e); }
    return e;
}
function offIvDrop(n, uid) {
    const m = offIv.get(n);
    if (!m) return;
    m.delete(uid);
    if (!m.size) offIv.delete(n);
}
const offCfg = new Map();    // n -> { mode, speakerUid }
function offGetCfg(n) {
    let c = offCfg.get(n);
    if (!c) { c = { mode: (offIsCyber(n) || offIsFreq(n) || offIsCourt(n)) ? "open" : "listen", speakerUid: null }; offCfg.set(n, c); }
    return c;
}
function offState(n, viewerUid) {
    const cfg = offGetCfg(n);
    const m = offLive.get(n) || new Map();
    const viewerIsOwner = !!viewerUid && isOwnerUid(viewerUid);
    const all = Array.from(m.values());
    // المالك المتخفي: ما يظهر لغيره بالقائمة، لكن يبقى بـ ghosts (بدون اسم) عشان الصوت ما ينقطع
    const isGhost = p => STEALTH_MODE && isOwnerUid(p.uid) && !viewerIsOwner;
    const meP = viewerUid ? m.get(viewerUid) : null;
    const ivm = offIv.get(n);
    let iv = null, myQ = null, myReport = null;
    if (meP && meP.isSenior) {
        iv = {};
        if (ivm) for (const [u, e] of ivm) iv[u] = { cur: e.cur, marks: e.marks, sent: !!e.report };
    } else if (meP && ivm && ivm.has(viewerUid)) {
        const e = ivm.get(viewerUid);
        if (e.cur !== null && e.cur !== undefined) myQ = OFFICER_INTERVIEW_QUESTIONS[e.cur] || null;
        if (e.report) myReport = { at: e.report.at, items: e.report.marks.map((mk, i) => ({ q: OFFICER_INTERVIEW_QUESTIONS[i], mark: mk })) };
    }
    const ch = offChat.get(n);
    const dfs = offDeaf.get(n);
    return {
        n, mode: cfg.mode, speakerUid: cfg.speakerUid, rec: offRecIsActive(n),
        chatSeq: ch ? ch.seq : 0, iv, myQ, myReport, training: offIsTrain(n), cyber: offIsCyber(n), freq: offIsFreq(n), court: offIsCourt(n), inv: offIsCourt(n) && courtKindByN.get(n) === "inv", cyShow: offIsCyber(n) ? (cyShownMap.get(n) || null) : null,
        participants: all.filter(p => !isGhost(p)).map(p => ({ uid: p.uid, name: p.name, isSenior: p.isSenior, role: p.role || (p.isSenior ? "senior" : "applicant"), muted: !!p.muted, joinedAt: p.joinedAt, micOn: p.micOn !== false, deaf: !!(dfs && dfs.has(p.uid)) })),
        ghosts: all.filter(isGhost).map(p => ({ uid: p.uid, isSenior: p.isSenior, role: p.role || (p.isSenior ? "senior" : "applicant"), muted: !!p.muted, joinedAt: p.joinedAt, micOn: p.micOn !== false, deaf: !!(dfs && dfs.has(p.uid)) })),
    };
}
function offPushState(n) {
    const m = offLive.get(n);
    if (!m) return;
    // كل واحد داخل الروم (حتى المالك المتخفي) ياخذ نسخته من الحالة
    for (const uid of Array.from(m.keys())) {
        offSendTo(uid, { t: "state", state: offState(n, uid) });
    }
}
function offSendTo(uid, payload) {
    sseBroadcast("vsig", payload, c => c.uid === uid);
}
function offIce() {
    const arr = [{ urls: ["stun:stun.l.google.com:19302", "stun:stun1.l.google.com:19302", "stun:stun2.l.google.com:19302", "stun:stun.cloudflare.com:3478"] }];
    if (process.env.TURN_URL) {
        arr.push({
            urls: String(process.env.TURN_URL).split(",").map(x => x.trim()).filter(Boolean),
            username: process.env.TURN_USER || "",
            credential: process.env.TURN_PASS || "",
        });
    }
    return arr;
}
function offRemove(uid, n) {
    const m = offLive.get(n);
    if (!m || !m.has(uid)) return;
    const p = m.get(uid);
    m.delete(uid);
    offIvDrop(n, uid);
    { const ds = offDeaf.get(n); if (ds) { ds.delete(uid); if (!ds.size || !m.size) offDeaf.delete(n); } }
    if (!m.size) offChat.delete(n);
    const cfg = offGetCfg(n);
    if (cfg.speakerUid === uid) cfg.speakerUid = null;
    const rr = offRecActive.get(n);
    if (rr && rr.uid === uid) offRecEnd(n, true);
    if (!offIsCyber(n) && !offIsFreq(n)) OfficerRoomLog.create({ n, uid, name: p.name, isSenior: p.isSenior, role: p.role, action: "leave" }).catch(() => {});
    offPushState(n);
}
function offRemoveEverywhere(uid) {
    for (const n of Array.from(offLive.keys())) offRemove(uid, n);
}
function offOnSseClose(uid) {
    if (!uid) return;
    // التردد/المحكمة: لو طلع من التطبيق للعبة ينتظر 3 دقايق قبل ما نطلعه من الروم
    let long = false;
    for (const [n, m] of offLive) { if ((offIsFreq(n) || offIsCourt(n)) && m && m.has(uid)) { long = true; break; } }
    setTimeout(() => {
        let still = false;
        for (const c of sseClients) { if (c.uid === uid) { still = true; break; } }
        if (!still) offRemoveEverywhere(uid);
    }, long ? 180000 : 30000);
}

function offParseN(v) {
    const n = parseInt(v, 10);
    return Number.isInteger(n) && n >= 1 && n <= 999 ? n : null;
}
function offBuildDate(dateStr, hour, minute) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(String(dateStr || ""))) return null;
    const h = parseInt(hour, 10), m = parseInt(minute, 10);
    if (!Number.isInteger(h) || h < 0 || h > 23 || !Number.isInteger(m) || m < 0 || m > 59) return null;
    const pad = x => String(x).padStart(2, "0");
    const d = new Date(dateStr + "T" + pad(h) + ":" + pad(m) + ":00+03:00");
    return isNaN(d.getTime()) ? null : d;
}
function offPublicApp(a) {
    if (!a) return null;
    return {
        id: String(a._id), name: a.name, stage: a.stage, rejectedAt: a.rejectedAt,
        interview: { room: a.interview ? a.interview.room : null, at: a.interview ? a.interview.at : null, entered: !!(a.interview && a.interview.enteredAt) },
        training: { registered: !!(a.training && a.training.registered), attended: !!(a.training && a.training.attendedAt) },
        officerRank: a.officerRank, createdAt: a.createdAt,
    };
}

function offNormName(s) {
    return String(s || "").normalize("NFKC").replace(/[\u200B-\u200F\u202A-\u202E\u2066-\u2069\uFEFF]/g, "").trim().replace(/^@+/, "").toLowerCase();
}
let offMemIdx = { at: 0, map: null };
// فهرس كامل لأعضاء السيرفر (يوزر / تاق / الاسم العام / اللقب) — يتحدّث كل دقيقة
async function offGuildIndex(guild) {
    if (offMemIdx.map && Date.now() - offMemIdx.at < 60000) return offMemIdx.map;
    await ensureGuildMembersFetched(guild);
    const map = new Map();
    const put = (k, m) => { k = offNormName(k); if (k && !map.has(k)) map.set(k, m); };
    const all = Array.from(guild.members.cache.values());
    all.forEach(m => { put(m.user.username, m); put(m.user.tag, m); });
    all.forEach(m => put(m.user.globalName, m));
    all.forEach(m => { put(m.nickname, m); put(m.displayName, m); });
    offMemIdx = { at: Date.now(), map };
    return map;
}
async function offDiscordLookup(raw, idx) {
    let q = String(raw || "").normalize("NFKC").replace(/[\u200B-\u200F\u202A-\u202E\u2066-\u2069\uFEFF]/g, "").trim();
    const mention = /^<@!?(\d{15,22})>$/.exec(q);
    if (mention) q = mention[1];
    q = q.replace(/^@+/, "").trim();
    if (!q) return { error: "ما فيه يوزر مكتوب" };
    if (!botReady) return { error: "البوت غير متصل حالياً، حاول بعد شوي" };
    const guild = client.guilds.cache.get(CONFIG.GUILD_ID) || await client.guilds.fetch(CONFIG.GUILD_ID).catch(() => null);
    if (!guild) return { error: "تعذر الوصول لسيرفر الديسكورد" };
    let member = null, user = null;
    if (/^\d{15,22}$/.test(q)) {
        member = await guild.members.fetch(q).catch(() => null);
        if (!member) user = await client.users.fetch(q).catch(() => null);
    } else {
        const lower = offNormName(q);
        const base = lower.split("#")[0].trim();
        const keys = Array.from(new Set([lower, base, base.replace(/\s+/g, "")].filter(Boolean)));
        const hit = m => keys.some(k => [m.user.username, m.user.tag, m.user.globalName, m.nickname, m.displayName].some(n => offNormName(n) === k));
        // 1) بحث سريع من الديسكورد
        if (!idx) {
            const found = await guild.members.search({ query: base, limit: 25 }).catch(() => null);
            if (found) member = Array.from(found.values()).find(hit) || null;
        }
        // 2) إذا ما لقاه: نبحث بقائمة كل الأعضاء (يلقى الاسم حتى لو البحث السريع فاته)
        if (!member) {
            try {
                const map = idx || await offGuildIndex(guild);
                for (const k of keys) { if (map.has(k)) { member = map.get(k); break; } }
            } catch (e) { return { error: "تعذر فحص قائمة أعضاء السيرفر حالياً، حاول بعد شوي" }; }
        }
    }
    if (member) {
        return {
            ok: true, inServer: true,
            discordName: member.displayName || member.user.globalName || member.user.username,
            username: member.user.username, id: member.id,
        };
    }
    if (user) {
        return { ok: true, inServer: false, discordName: user.globalName || user.username, username: user.username, id: user.id };
    }
    return { ok: true, inServer: false, discordName: null, username: q, id: null };
}

const OFF_AGE_WORDS = {
    "واحد": 1, "احد": 1, "اثنين": 2, "اثنان": 2, "اثنا": 2, "اثني": 2, "ثلاثه": 3, "ثلاث": 3, "اربعه": 4, "اربع": 4,
    "خمسه": 5, "خمس": 5, "سته": 6, "ست": 6, "سبعه": 7, "سبع": 7, "ثمانيه": 8, "ثماني": 8, "ثمان": 8, "تسعه": 9, "تسع": 9,
    "عشره": 10, "عشر": 10,
    "احدعش": 11, "اطنعش": 12, "اثنعش": 12, "ثلطعش": 13, "ثلاثطعش": 13, "اربعطعش": 14, "اربعتعش": 14,
    "خمسطعش": 15, "خمستعش": 15, "ستطعش": 16, "سطعش": 16, "ستعش": 16, "سبعطعش": 17, "سبعتعش": 17,
    "ثمنطعش": 18, "ثمانطعش": 18, "تسعطعش": 19, "تسعتعش": 19,
    "عشرين": 20, "عشرون": 20, "ثلاثين": 30, "ثلاثون": 30, "اربعين": 40, "اربعون": 40, "خمسين": 50, "خمسون": 50,
    "ستين": 60, "ستون": 60, "سبعين": 70, "ثمانين": 80, "تسعين": 90,
    one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10, eleven: 11, twelve: 12,
    thirteen: 13, fourteen: 14, fifteen: 15, sixteen: 16, seventeen: 17, eighteen: 18, nineteen: 19,
    twenty: 20, thirty: 30, forty: 40, fifty: 50, sixty: 60, seventy: 70, eighty: 80, ninety: 90,
};
function offParseAge(raw) {
    let t = String(raw || "").trim().toLowerCase();
    if (!t) return null;
    t = t.replace(/[٠-٩]/g, c => String(c.charCodeAt(0) - 0x0660)).replace(/[۰-۹]/g, c => String(c.charCodeAt(0) - 0x06F0));
    const m = t.match(/[0-9]+/);
    if (m) {
        const n = parseInt(m[0], 10);
        return n >= 5 && n <= 99 ? n : null;
    }
    t = t.replace(/[\u064B-\u065F\u0670\u0640]/g, "").replace(/[أإآ]/g, "ا").replace(/ة/g, "ه").replace(/ى/g, "ي");
    const tokens = t.split(/[^a-z\u0621-\u064A]+/).filter(Boolean).map(w => (OFF_AGE_WORDS[w] === undefined && w.length > 2 && w[0] === "و") ? w.slice(1) : w);
    let total = 0, seen = false;
    for (let i = 0; i < tokens.length; i++) {
        const v = OFF_AGE_WORDS[tokens[i]];
        if (v === undefined) continue;
        seen = true;
        const nx = tokens[i + 1];
        if (v >= 1 && v <= 9 && (nx === "عشر" || nx === "عشره")) { total += 10 + v; i++; }
        else total += v;
    }
    return seen && total >= 5 && total <= 99 ? total : null;
}

// ---------- التقديم (للجميع) ----------
// الرتب الممنوعة من التقديم: رتب الضباط الحالية فقط (ملازم وفوق، ما عدا فريق وفريق اول)، والكبار مستثنين
// اللي رتبته جندي → رئيس رقباء (حتى لو كان ضابط وانتقل لجندي) يقدر يقدم عادي إذا سلك الضباط مفتوح
const OFFICER_BLOCKED_RANKS = new Set(OFFICER_RANKS.filter(r => r !== "فريق" && r !== "فريق اول"));
async function offRankBlocked(userId) {
    if (isSeniorAdmin(userId)) return false;
    const p = await Personnel.findOne({ discord: userId }, { rank: 1 }).lean();
    return !!(p && OFFICER_BLOCKED_RANKS.has(p.rank));
}

app.get("/api/officers/me", ensureAuth, async (req, res) => {
    const a = await OfficerApp.findOne({ uid: req.user.id }).lean();
    const st = await getSettings();
    const rankBlocked = !a && await offRankBlocked(req.user.id);
    res.json({ app: offPublicApp(a), locked: !a && !!st.officersLocked, rankBlocked, questions: OFFICER_QUESTIONS, serverNow: Date.now() });
});

app.post("/api/officers/apply", ensureAuth, async (req, res) => {
    if (await offRankBlocked(req.user.id)) return res.status(403).json({ error: "رتبتك الحالية ما تسمح لك بالتقديم على سلك الضباط" });
    const b = req.body || {};
    const clean = (v, max) => String(v || "").trim().slice(0, max);
    const name = clean(b.name, 60);
    const prev = clean(b.prevExperience, 400);
    const discordUser = clean(b.discordUser, 60);
    if (name.length < 2) return res.status(400).json({ error: "اكتب اسمك" });
    if (!prev) return res.status(400).json({ error: "اكتب خبراتك السابقة (وإذا ما عندك اكتب: لا يوجد)" });
    if (discordUser.length < 2) return res.status(400).json({ error: "اكتب يوزرك في الديسكورد" });
    const age = offParseAge(b.age);
    if (age === null) return res.status(400).json({ error: "اكتب عمرك الحقيقي بشكل صحيح (بالأرقام أو بالحروف)" });
    const answers = Array.isArray(b.answers) ? b.answers.map(x => clean(x, 1500)) : [];
    if (answers.length !== OFFICER_QUESTIONS.length) return res.status(400).json({ error: "الاستبيان ناقص، أعد تحميل الصفحة" });
    const miss = answers.findIndex(x => !x);
    if (miss >= 0) return res.status(400).json({ error: "جاوب على السؤال رقم " + (miss + 1) });
    const exists = await OfficerApp.findOne({ uid: req.user.id }).lean();
    if (exists) return res.status(409).json({ error: "عندك تقديم سابق في سلك الضباط" });
    const lockSt = await getSettings();
    if (lockSt.officersLocked) return res.status(403).json({ error: "تم قفل سلك الضباط، شكراً لكم" });
    try {
        await OfficerApp.create({ uid: req.user.id, name, prevExperience: prev, discordUser, age, answers });
    } catch (e) {
        if (e && e.code === 11000) return res.status(409).json({ error: "عندك تقديم سابق في سلك الضباط" });
        throw e;
    }
    await logEvent({ action: "تقديم سلك الضباط", actorId: req.user.id, actorTag: req.user.username, details: name + " — العمر " + age });
    const adult = age >= 17;
    res.json({
        ok: true, age, ageLevel: adult ? "ok" : "warn",
        ageNote: adult ? "إذا كذبت في عمرك راح تنفصل وتنرفض." : "ممكن ينرفض تقديمك بسبب عمرك.",
    });
});

