// ---------- روم التحقيق السيبراني الصوتي (يستخدم نفس محرك صوت المقابلة) ----------
let cyMidSeq = 0;
function cyMid() { return Date.now() * 10 + (cyMidSeq++ % 10); }
app.post("/api/officers/rooms/:n/join", ensureAuth, async (req, res, next) => {
    const n = offParseN(req.params.n);
    if (!n || !offIsCyber(n)) return next();
    const uid = req.user.id;
    const cc = await CyberCase.findOne({ voiceN: n, status: "investigating" });
    if (!cc) return res.status(404).json({ error: "التحقيق غير موجود أو منتهي" });
    const rl = await cyberRoleOf(uid);
    const isT = cc.targetUid === uid;
    if (underInvestigation.has(uid) && !isT) return res.status(403).json({ error: "🔒 حسابك تحت التحقيق السيبراني" });
    if (!isT && !rl.isMember && !rl.isLeader) return res.status(403).json({ error: "ليست لديك صلاحية دخول هذا الروم" });
    if (!isT && (cc.kicked || []).includes(uid)) return res.status(403).json({ error: "🚫 تم طردك من هذا التحقيق" });
    if (cc.shown && !cyShownMap.has(n)) cyShownMap.set(n, cc.shown);
    const role = isT ? "target" : (rl.isLeader ? "leader" : "member");
    const name = await cyName(uid);
    for (const otherN of Array.from(offLive.keys())) { if (otherN !== n) offRemove(uid, otherN); }
    let m = offLive.get(n);
    if (!m) { m = new Map(); offLive.set(n, m); }
    const existing = Array.from(m.keys()).filter(u => u !== uid);
    m.set(uid, { uid, name, isSenior: false, role, muted: (cc.muted || []).includes(uid), joinedAt: Date.now() });
    offPushState(n);
    const chat = (cc.chat || []).filter(x => !x.system && x.mid).slice(-50).map(x => ({ id: x.mid, uid: x.uid, name: x.name, isSenior: x.role === "leader", text: x.text, at: new Date(x.at).getTime() }));
    res.json({ ok: true, state: offState(n, uid), existing, iceServers: offIce(), ivQuestions: null, chat, caseId: String(cc._id) });
});
app.post("/api/officers/rooms/:n/chat", ensureAuth, async (req, res, next) => {
    const n = offParseN(req.params.n);
    if (!n || !offIsCyber(n)) return next();
    const m = offLive.get(n);
    const me = m ? m.get(req.user.id) : null;
    if (!me) return res.status(404).json({ error: "أنت لست داخل الروم" });
    if (me.muted) return res.status(403).json({ error: "🔇 تم إسكاتك في هذا التحقيق" });
    const text = String((req.body || {}).text || "").trim().slice(0, 500);
    if (!text) return res.status(400).json({ error: "اكتب رسالة" });
    if (Date.now() - (me.lastChatAt || 0) < 800) return res.status(429).json({ error: "على رواقك شوي" });
    me.lastChatAt = Date.now();
    const cc = await CyberCase.findOne({ voiceN: n, status: "investigating" }, { targetUid: 1 });
    if (!cc) return res.status(404).json({ error: "التحقيق منتهي" });
    const mid = cyMid();
    await CyberCase.updateOne({ _id: cc._id }, { $push: { chat: { $each: [{ uid: me.uid, name: me.name, role: me.role, text, mid }], $slice: -500 } } });
    const msg = { id: mid, uid: me.uid, name: me.name, isSenior: me.role === "leader", text, at: Date.now() };
    for (const u of Array.from(m.keys())) offSendTo(u, { t: "chat", n, msg });
    cyberPush(cc);
    res.json({ ok: true });
});
app.get("/api/officers/rooms/:n/chat", ensureAuth, async (req, res, next) => {
    const n = offParseN(req.params.n);
    if (!n || !offIsCyber(n)) return next();
    const m = offLive.get(n);
    if (!m || !m.has(req.user.id)) return res.status(404).json({ error: "أنت لست داخل الروم" });
    const after = parseInt(req.query.after, 10) || 0;
    const cc = await CyberCase.findOne({ voiceN: n }, { chat: 1 }).lean();
    const list = ((cc && cc.chat) || []).filter(x => !x.system && x.mid && x.mid > after);
    res.json({ msgs: list.map(x => ({ id: x.mid, uid: x.uid, name: x.name, isSenior: x.role === "leader", text: x.text, at: new Date(x.at).getTime() })), seq: list.length ? list[list.length - 1].mid : after });
});

// ---------- دخول رومات الترددات المشتركة (910..919) والمحكمة (950..979) ----------
app.post("/api/officers/rooms/:n/join", ensureAuth, async (req, res, next) => {
    const n = offParseN(req.params.n);
    if (!n || !offIsFreq(n)) return next();
    const uid = req.user.id;
    if (!(await freqExists(n))) return res.status(404).json({ error: "هذا التردد غير موجود" });
    if (underCourt.has(uid)) return res.status(403).json({ error: "⚖️ أنت مطلوب للمحكمة العسكرية" });
    const name = await cyName(uid);
    for (const otherN of Array.from(offLive.keys())) { if (otherN !== n) offRemove(uid, otherN); }
    let m = offLive.get(n);
    if (!m) { m = new Map(); offLive.set(n, m); }
    const existing = Array.from(m.keys()).filter(u => u !== uid);
    m.set(uid, { uid, name, isSenior: false, role: isSeniorAdmin(uid) ? "senior" : "member", muted: false, joinedAt: Date.now() });
    offPushState(n);
    const ch = offChat.get(n);
    res.json({ ok: true, state: offState(n, uid), existing, iceServers: offIce(), ivQuestions: null, chat: ch ? ch.msgs : [] });
});
app.post("/api/officers/rooms/:n/join", ensureAuth, async (req, res, next) => {
    const n = offParseN(req.params.n);
    if (!n || !offIsCourt(n)) return next();
    const uid = req.user.id;
    const cc = await CourtCase.findOne({ voiceN: n, status: "active" });
    if (!cc) return res.status(404).json({ error: "المحكمة غير موجودة أو انتهت" });
    const isT = courtIsTarget(cc, uid);
    const r = await courtRole(uid);
    if (!isT && !r.staff) return res.status(403).json({ error: "ليست لديك صلاحية دخول المحكمة" });
    if (!isT && underCourt.has(uid)) return res.status(403).json({ error: "⚖️ أنت مطلوب للمحكمة العسكرية" });
    if (!isT && (cc.kicked || []).includes(uid)) return res.status(403).json({ error: "🚫 تم طردك من هذه المحكمة" });
    const role = isT ? "target" : (r.senior ? "senior" : (r.leader ? "mpl" : "mp"));
    const name = await cyName(uid);
    for (const otherN of Array.from(offLive.keys())) { if (otherN !== n) offRemove(uid, otherN); }
    let m = offLive.get(n);
    if (!m) { m = new Map(); offLive.set(n, m); }
    const existing = Array.from(m.keys()).filter(u => u !== uid);
    const wasInC = m.has(uid);
    m.set(uid, { uid, name, isSenior: false, role, muted: (cc.muted || []).includes(uid), joinedAt: Date.now() });
    if (!wasInC) OfficerRoomLog.create({ n, uid, name, isSenior: !!r.senior, role, action: "join" }).catch(() => {});
    offPushState(n);
    const ch = offChat.get(n);
    res.json({ ok: true, state: offState(n, uid), existing, iceServers: offIce(), ivQuestions: null, chat: ch ? ch.msgs : [], caseId: String(cc._id) });
});

// ---------- الروم الصوتي ----------
app.post("/api/officers/rooms/:n/join", ensureAuth, async (req, res) => {
    const n = offParseN(req.params.n);
    if (!n) return res.status(400).json({ error: "روم غير صحيح" });
    const uid = req.user.id;
    const senior = isSeniorAdmin(uid);
    let name = req.user.username;
    let appDoc = null;
    const isTrain = offIsTrain(n);
    let role = senior ? "senior" : "applicant";
    if (isTrain) {
        if (!senior) {
            if (await offIsTrainer(uid)) {
                role = "trainer";
                const pr = await Personnel.findOne({ discord: uid }, { registeredName: 1 }).lean();
                name = (pr && pr.registeredName) || name;
            } else {
                const tr = await OfficerApp.findOne({ uid, stage: "training", "training.registered": true }).lean();
                if (!tr) return res.status(403).json({ error: "ما أنت مسجل متدرب بالتدريب" });
                role = "trainee";
                name = tr.name || name;
            }
        }
    } else if (senior) {
        if (!(await OfficerRoom.exists({ n }))) return res.status(404).json({ error: "هذا الروم غير موجود" });
    } else {
        appDoc = await OfficerApp.findOne({ uid, stage: "interview", "interview.room": n });
        if (!appDoc || !appDoc.interview || !appDoc.interview.at) return res.status(403).json({ error: "ما عندك مقابلة بهذا الروم" });
        if (Date.now() < new Date(appDoc.interview.at).getTime() - OFFICER_OPEN_BEFORE_MS) {
            return res.status(403).json({ error: "الروم ينفتح قبل موعد مقابلتك بخمس دقايق" });
        }
        name = appDoc.name || name;
    }
    for (const otherN of Array.from(offLive.keys())) { if (otherN !== n) offRemove(uid, otherN); }
    let m = offLive.get(n);
    if (!m) { m = new Map(); offLive.set(n, m); }
    const existing = Array.from(m.keys()).filter(u => u !== uid);
    const wasIn = m.has(uid);
    m.set(uid, { uid, name, isSenior: senior, role, muted: role === "trainee", joinedAt: Date.now() });
    if (appDoc) { const ive = offIvGet(n, uid); ive.cur = null; ive.report = null; ive.marks = offIvClean(appDoc.interview && appDoc.interview.marks); }
    offPushState(n);
    if (!wasIn) OfficerRoomLog.create({ n, uid, name, isSenior: senior, role, action: "join" }).catch(() => {});
    if (appDoc && !appDoc.interview.enteredAt) {
        await OfficerApp.updateOne({ _id: appDoc._id }, { $set: { "interview.enteredAt": new Date() } });
    }
    const chJ = offChat.get(n);
    res.json({ ok: true, state: offState(n, uid), existing, iceServers: offIce(), ivQuestions: senior ? OFFICER_INTERVIEW_QUESTIONS : null, chat: chJ ? chJ.msgs : [] });
});

