app.post("/api/cyber/cases/:id/show", ensureAuth, async (req, res) => {
    try {
        const x = await cyAccess(req, res, true); if (!x) return;
        if (x.c.status !== "investigating") return res.status(400).json({ error: "التحقيق منتهي" });
        const ref = String((req.body && req.body.ref) || "");
        const name = await cyName(req.user.id);
        let shown = null;
        if (ref) {
            const op = await cyResolveOp(ref, x.c.targetUid);
            if (!op) return res.status(404).json({ error: "العملية غير موجودة أو مو تابعة للعضو" });
            shown = { ref: op.ref, title: op.title, lines: op.lines, opAt: op.opAt, hasPhoto: op.hasPhoto, byName: name, at: new Date() };
        }
        await CyberCase.updateOne({ _id: x.c._id }, { $set: { shown } });
        if (x.c.voiceN) {
            if (shown) cyShownMap.set(x.c.voiceN, shown); else cyShownMap.delete(x.c.voiceN);
            offPushState(x.c.voiceN);
        }
        await cySystemMsg(x.c._id, shown ? `📋 عرض ${name} على ${x.c.targetName} عملية: ${shown.title}` : `🙈 أخفى ${name} العملية المعروضة`);
        cyberPush(x.c);
        res.json({ ok: true });
    } catch (e) { res.status(500).json({ error: "تعذر عرض العملية" }); }
});

app.post("/api/cyber/cases/:id/kick", ensureAuth, async (req, res) => {
    try {
        const x = await cyAccess(req, res, true); if (!x) return;
        if (x.c.status !== "investigating") return res.status(400).json({ error: "التحقيق منتهي" });
        const target = String((req.body && req.body.uid) || "");
        if (!target || target === req.user.id) return res.status(400).json({ error: "حدد الشخص" });
        if (isOwnerUid(target) && !isOwnerUid(req.user.id)) return res.status(403).json({ error: "ما يمديك تطرد المالك" });
        const name = await cyName(req.user.id);
        const tName = await cyName(target);
        if (target !== x.c.targetUid) await CyberCase.updateOne({ _id: x.c._id }, { $addToSet: { kicked: target } });
        if (x.c.voiceN) { offSendTo(target, { t: "kicked", n: x.c.voiceN }); offRemove(target, x.c.voiceN); }
        await cySystemMsg(x.c._id, `🚫 ${name} طرد ${tName} من التحقيق`);
        cyberPush(x.c);
        res.json({ ok: true });
    } catch (e) { res.status(500).json({ error: "تعذر الطرد" }); }
});

// ======================================================================
//  ⚡ إضافات فلاش: الإشعارات (Web Push) • البصمة • الترددات المشتركة • المحكمة العسكرية • الاستلام
//  (يحتاج مكتبة web-push:   npm install web-push)
// ======================================================================
let webpush = null;
try { webpush = require("web-push"); }
catch (e) { console.log("⚠️ مكتبة web-push غير مثبتة — الإشعارات معطّلة. شغّل: npm install web-push"); }

const validDevId = v => typeof v === "string" && /^[a-zA-Z0-9-]{8,64}$/.test(v);
const cleanDevName = v => String(v || "جهاز").replace(/[\r\n<>]/g, "").slice(0, 40);

// ---------- الأجهزة + حالة التطبيق (PWA) ----------
const PushDevice = mongoose.model("PushDevice", new mongoose.Schema({
    id: { type: String, unique: true, required: true },
    uid: { type: String, default: null, index: true },
    name: { type: String, default: "جهاز" },
    standalone: { type: Boolean, default: false },
    sub: { type: mongoose.Schema.Types.Mixed, default: null },
    lastSeen: { type: Date, default: Date.now },
    enteredAt: { type: Date, default: null },
    createdAt: { type: Date, default: Date.now },
}));
// الأجهزة المكررة: لكل حساب نعتمد آخر جهاز دخل فيه (المتصل أولاً)، والباقي "مكرر" ما ينرسل لهم شي
async function pushDupSet() {
    const all = await PushDevice.find({ uid: { $ne: null } }, { id: 1, uid: 1, enteredAt: 1, lastSeen: 1 }).lean();
    const best = new Map();
    for (const d of all) {
        const sc = (devIsOnline(d.id) ? 1e15 : 0) + (+new Date(d.enteredAt || d.lastSeen || 0));
        const b = best.get(d.uid);
        if (!b || sc > b.sc) best.set(d.uid, { id: d.id, sc });
    }
    return new Set(all.filter(d => best.get(d.uid).id !== d.id).map(d => d.id));
}
async function pushableDevs(filter) {
    const dup = await pushDupSet();
    const list = await PushDevice.find(Object.assign({ sub: { $ne: null } }, filter || {})).lean();
    return list.filter(d => !dup.has(d.id));
}
// حساب دخل مرة من "تطبيق الويب" => المتصفح يتقفل عليه ويقوله ادخل من التطبيق
const PwaInstall = mongoose.model("PwaInstall", new mongoose.Schema({ uid: { type: String, unique: true }, at: { type: Date, default: Date.now } }));
const pwaSeen = new Map();
function markPwa(uid) {
    if (!uid) return;
    if (Date.now() - (pwaSeen.get(uid) || 0) < 6 * 3600 * 1000) return;
    pwaSeen.set(uid, Date.now());
    PwaInstall.updateOne({ uid }, { $set: { at: new Date() } }, { upsert: true }).catch(() => {});
    // دخل من التطبيق => نحذف أجهزة المتصفح (الجوال) حقته
    PushDevice.deleteMany({ uid, standalone: false, name: /^(آيفون|آيباد|أندرويد)/ }).catch(() => {});
}
// حضور الأجهزة (متصل/غير متصل) عن طريق نفس اتصال /api/events
const devConns = new Map();
const devGrace = new Set();
const devIsOnline = id => (devConns.get(id) || 0) > 0 || devGrace.has(id);
const activeDev = new Map(); // uid -> آخر جهاز دخل بالحساب
function devOnConnect(c, q) {
    const id = c.did, uid = c.uid;
    const standalone = String(q.sa) === "1";
    c.sa = standalone;
    c.mob = /^(آيفون|آيباد|أندرويد)/.test(cleanDevName(q.dn));
    devConns.set(id, (devConns.get(id) || 0) + 1);
    devGrace.delete(id);
    (async () => {
        if (standalone) {
            // دخل من تطبيق الويب => المتصفح (جوال) ينقفل ويتحذف ويبقى التطبيق
            sseBroadcast("pwakick", { t: Date.now() }, cl => cl.uid === uid && cl.mob && cl.sa === false);
            PushDevice.deleteMany({ uid, standalone: false, name: /^(آيفون|آيباد|أندرويد)/, id: { $ne: id } }).catch(() => {});
            markPwa(uid);
        } else if (c.mob && await PwaInstall.exists({ uid })) {
            return; // متصفح جوال وعنده التطبيق: ما ياخذ مكان التطبيق ولا ينسجل
        }
        // جهاز واحد بالحساب: آخر جهاز يدخل يفوز
        if (activeDev.get(uid) !== id) {
            activeDev.set(uid, id);
            sseBroadcast("sessionkick", { t: Date.now() }, cl => cl.uid === uid && cl.did && cl.did !== id && !(standalone && cl.mob && cl.sa === false));
        }
        await PushDevice.updateOne({ id }, { $set: { uid, name: cleanDevName(q.dn), standalone, lastSeen: new Date(), enteredAt: new Date() }, $setOnInsert: { createdAt: new Date() } }, { upsert: true });
    })().catch(() => {});
}
function devOnClose(c) {
    const id = c && c.did;
    if (!id) return;
    const n = (devConns.get(id) || 1) - 1;
    if (n > 0) { devConns.set(id, n); return; }
    devConns.delete(id); devGrace.add(id);
    PushDevice.updateOne({ id }, { $set: { lastSeen: new Date() } }).catch(() => {});
    setTimeout(() => { if (!devConns.get(id)) devGrace.delete(id); }, 5000);
}

// ---------- مفاتيح VAPID (من المتغيرات أو تنحفظ بالداتابيس عشان ما تتغير) ----------
let vapidPromise = null;
function ensureVapid() {
    if (!webpush) return Promise.resolve(null);
    if (vapidPromise) return vapidPromise;
    vapidPromise = (async () => {
        let pub = process.env.VAPID_PUBLIC_KEY, priv = process.env.VAPID_PRIVATE_KEY;
        if (!pub || !priv) {
            const s = await getSettings();
            if (s.vapid && s.vapid.publicKey && s.vapid.privateKey) { pub = s.vapid.publicKey; priv = s.vapid.privateKey; }
            else {
                const k = webpush.generateVAPIDKeys();
                pub = k.publicKey; priv = k.privateKey;
                s.vapid = { publicKey: pub, privateKey: priv };
                s.markModified("vapid");
                await s.save();
                console.log("🔑 تم توليد مفاتيح VAPID وحفظها بالداتابيس");
            }
        }
        webpush.setVapidDetails(process.env.VAPID_SUBJECT || "mailto:admin@flash.sa", pub, priv);
        return pub;
    })().catch(e => { vapidPromise = null; console.error("❌ VAPID:", e.message); return null; });
    return vapidPromise;
}
// صفحة الإشعار: لما يضغط عليه يدخله على موضوعه (التحضير / الغياب بعذر / التكت / المحكمة)، والباقي (إعلانات الكبار) للصفحة الرئيسية
function pushUrlFor(tag) {
    const t = String(tag || "");
    if (!t) return "/";
    if (t === "reception" || t === "att-note") return "/?go=att";
    if (t.startsWith("att-over-")) return "/?go=hcatt";
    if (t === "recabs" || t.startsWith("rmabs-") || t.startsWith("excuse-res-")) return "/?go=excuse";
    if (t.startsWith("excuse-hc-")) return "/?go=hcexcuse";
    if (t === "court" || t === "court-soon" || t === "court-req" || t === "unkick") return "/?go=court";
    if (t.startsWith("warn-")) return "/?go=warn";
    if (t.startsWith("fraud-")) return "/?go=fraud";
    return "/";
}
async function sendPushTo(devs, opts) {
    const key = await ensureVapid();
    if (!key) return { sent: 0, failed: [], unavailable: true };
    const payload = JSON.stringify({
        title: String(opts.title || CONFIG.SITE_NAME).slice(0, 80),
        body: String(opts.body || "").slice(0, 200),
        url: opts.url || pushUrlFor(opts.tag),
        tag: opts.tag || undefined,
        urgent: opts.urgent ? true : undefined,
        inapp: opts.inapp ? true : undefined,
    });
    const list = (devs || []).filter(d => d && d.sub && d.sub.endpoint);
    let sent = 0; const failed = [];
    for (let i = 0; i < list.length; i += 40) {
        await Promise.all(list.slice(i, i + 40).map(async d => {
            try { await webpush.sendNotification(d.sub, payload, { TTL: opts.ttl || 3600, urgency: "high" }); sent++; }
            catch (e) {
                failed.push({ id: d.id, name: d.name, code: e.statusCode || 0 });
                if (e.statusCode === 404 || e.statusCode === 410) PushDevice.updateOne({ id: d.id }, { $set: { sub: null } }).catch(() => {});
                else console.log("❌ push:", d.name, e.statusCode || "", e.body || e.message);
            }
        }));
    }
    return { sent, failed };
}
// يرسل للمتصل وغير المتصل (كل جهاز مفعّل الإشعارات)
// ═══════════ 🔔 نظام الإشعارات (نفس نظام البنك) ═══════════
// كل إشعار لعضو يتسجّل هنا: داخل التطبيق يطلع توست تحت يمين (أزرق معلومة / أخضر نجاح / برتقالي تنبيه)،
// والإنذار يطلع نافذة حمراء منبثقة بصوت لين تضغط «فهمت». لو العضو برّا التطبيق يوصله Push عادي، وأول ما يدخل يطلع له.
const FlNotif = mongoose.model("FlNotif", new mongoose.Schema({
    uid: { type: String, index: true },
    kind: String,                                  // بادئة الـ tag (att-over- / court / warn- ...)
    label: String,                                 // اسم النوع اللي يظهر بعنوان الإشعار
    type: { type: String, default: "info" },       // info / success / warning / danger
    body: String,
    url: { type: String, default: "/" },           // وين يودّيك الضغط على الإشعار (?go=...)
    read: { type: Boolean, default: false },
    createdAt: { type: Date, default: Date.now, index: true },
}));
// كل نوع إشعار له لونه واسمه ووجهته (يتحدد بالـ tag): [بادئة الـ tag, النوع, العنوان]
const FL_NOTIF_KINDS = [
    ["att-over-",   "warning", "🚨 تجاوز الحضور"],        // برتقالي → يودّي لتجاوز الحضور
    ["att-note",    "warning", "⏱️ نسيت الانصراف"],
    ["recabs",      "warning", "❌ غياب عن الاستلام"],
    ["rmabs-",      "warning", "❌ غياب عن الاستلام"],
    ["excuse-res-", "info",    "🩺 قرار العذر"],
    ["excuse-hc-",  "info",    "🩺 عذر ينتظر قرارك"],
    ["excuse-",     "info",    "🩺 عذر غياب جديد"],
    ["court-soon",  "warning", "⚖️ موعد تحقيق"],
    ["court-req",   "info",    "⚖️ طلب تحقيق"],
    ["court",       "danger",  "⚖️ مطلوب للتحقيق الحين"],  // أحمر منبثق
    ["unkick",      "success", "🔓 فك الطرد"],
    ["fraud-",      "danger",  "🛡️ تلاعب محتمل"],         // أحمر منبثق
    ["cert-",       "success", "📜 شهادة جديدة"],
    ["ticket-",     "info",    "💬 رد على تكتك"],
    ["warn-",       "danger",  "🚨 إنذار"],               // التحذير الرسمي أحمر (نافذة)
    ["notice-",     "warning", "📌 إشعار إداري"],          // الإشعار الإداري توست برتقالي
    ["adm-",        "info",    "📢 رسالة من الإدارة"],     // إشعار مخصص من الكبار (النوع يتحدد من level)
    ["bank-",       "info",    "🏦 بنك فلاش"],
];
function flNotifMeta(opts) {
    const tag = String(opts.tag || "");
    const m = FL_NOTIF_KINDS.find(k => tag.startsWith(k[0]));
    const type = ["info", "success", "warning", "danger"].includes(opts.level) ? opts.level : (m ? m[1] : "info");
    return { type, label: String(opts.label || (m ? m[2] : "🔔 إشعار")).slice(0, 60), kind: m ? m[0] : "gen" };
}
async function flRecordNotif(uid, opts) {
    try {
        if (!uid || !opts || opts.noRecord || !opts.body) return;
        const meta = flNotifMeta(opts);
        const doc = await FlNotif.create({ uid: String(uid), kind: meta.kind, label: meta.label, type: meta.type, body: String(opts.body).slice(0, 300), url: opts.url || pushUrlFor(opts.tag) });
        sseBroadcast("fnotif", { id: String(doc._id) }, c => c.uid === String(uid));
    } catch (e) { console.error("❌ fnotif:", e.message); }
}
setInterval(() => { FlNotif.deleteMany({ createdAt: { $lt: new Date(Date.now() - 30 * 86400000) } }).catch(() => {}); }, 6 * 3600 * 1000).unref();
app.get("/api/fnotif", async (req, res) => {
    if (!req.isAuthenticated()) return res.json({ list: [] });
    try {
        await flConvertNotices(req.user.id);
        const list = await FlNotif.find({ uid: req.user.id, read: false }).sort({ createdAt: -1 }).limit(20).lean();
        const since = parseInt(req.query.since, 10);
        const unseen = since > 0 ? await FlNotif.countDocuments({ uid: req.user.id, createdAt: { $gt: new Date(since) } }) : 0;
        res.json({ unseen, list: list.map(n => ({ id: String(n._id), type: n.type, kind: n.kind, label: n.label, body: n.body, url: n.url, createdAt: n.createdAt })) });
    } catch (e) { res.json({ list: [] }); }
});
