const pushSendThrottle = new Map();
app.post("/api/senior/push/send", ensureSeniorAdmin, async (req, res) => {
    if (Date.now() - (pushSendThrottle.get(req.user.id) || 0) < 1500) return res.status(429).json({ error: "على رواقك شوي" });
    pushSendThrottle.set(req.user.id, Date.now());
    const b = req.body || {};
    const title = String(b.title || "").trim().slice(0, 60) || CONFIG.PUSH_DEFAULT_TITLE;
    const body = String(b.body || "").trim().slice(0, 160) || CONFIG.PUSH_DEFAULT_BODY;
    if (!webpush) return res.status(503).json({ error: "مكتبة web-push غير مثبتة على السيرفر" });
    let devs = [];
    if (b.all) devs = await pushableDevs();
    else if (validDevId(b.id)) {
        const d = await PushDevice.findOne({ id: b.id }).lean();
        if (!d || !d.sub) return res.status(404).json({ error: "هذا الجهاز ما فعّل الإشعارات" });
        if ((await pushDupSet()).has(d.id)) return res.status(400).json({ error: "هذا الجهاز مكرر، ما يمديك ترسل له" });
        devs = [d];
    } else return res.status(400).json({ error: "حدد الجهاز" });
    if (!devs.length) return res.status(404).json({ error: "ما فيه أجهزة مفعّلة للإشعارات" });
    const s = await getSettings();
    s.notifTitle = title; s.notifBody = body;
    await s.save();
    sseBroadcast("pushtext", { title, body, by: req.user.id }, c => !!c.uid && isSeniorAdmin(c.uid));
    const r = await sendPushTo(devs, { title, body });
    await logEvent({ action: "إرسال إشعار", actorId: req.user.id, actorTag: req.user.username, details: (b.all ? "للجميع" : "لجهاز") + " — " + title + ": " + body + " (وصل " + r.sent + ")" });
    res.json({ sent: r.sent, failed: r.failed.map(f => ({ id: f.id, name: f.name })) });
});

// إشعار العضو من التكت (للإدارة والكبار): "رد عليك الإداري على تكتك"
const ticketNotifyThrottle = new Map();
app.post("/api/support/admin/tickets/:id/notify", async (req, res) => {
    if (!req.isAuthenticated() || !(await isSupportAdmin(req.user.id))) return res.status(403).json({ error: "للإدارة فقط" });
    if (!mongoose.Types.ObjectId.isValid(req.params.id)) return res.status(400).json({ error: "رقم غير صحيح" });
    const t = await SupportTicket.findById(req.params.id, { uid: 1, no: 1 }).lean();
    if (!t) return res.status(404).json({ error: "التكت غير موجود" });
    if (!t.uid) return res.status(400).json({ error: "هذا التكت لزائر بدون حساب، ما نقدر نرسل له إشعار" });
    const k = String(t._id);
    if (Date.now() - (ticketNotifyThrottle.get(k) || 0) < 15000) return res.status(429).json({ error: "تم إرسال إشعار قبل شوي" });
    const r = await pushUid(t.uid, { title: CONFIG.SITE_NAME, body: "رد عليك الإداري على تكتك ⚡", tag: "ticket-" + t.no, url: "/?ticket=" + String(t._id) });
    if (!r.sent) return res.status(404).json({ error: "العضو ما فعّل الإشعارات على أي جهاز" });
    ticketNotifyThrottle.set(k, Date.now());
    res.json({ ok: true, sent: r.sent });
});

// ---------- البصمة (حضور / انصراف) ----------
const AttStatus = mongoose.model("AttStatus", new mongoose.Schema({
    uid: { type: String, unique: true, required: true },
    name: String,
    status: { type: String, enum: ["in", "out"], default: "out" },
    lastCheckInAt: { type: Date, default: null },
    lastCheckOutAt: { type: Date, default: null },
    updatedAt: { type: Date, default: Date.now },
}));
const AttLogSchema = new mongoose.Schema({
    uid: String, name: String, type: String, at: { type: Date, default: Date.now }, by: { type: String, default: null },
});
AttLogSchema.index({ at: -1 });
const AttLog = mongoose.model("AttLog", AttLogSchema);
// كبار المسؤولين ما يلزمهم بصمة (بس تقدر يبصمون إذا حبوا)
const attRequired = uid => true;
async function getAttState(uid) {
    const st = await AttStatus.findOne({ uid }, { status: 1, lastCheckInAt: 1 }).lean();
    return { status: st && st.status === "in" ? "in" : "out", at: st ? st.lastCheckInAt : null };
}
app.get("/api/attendance/status", ensureAuth, async (req, res) => {
    res.json(await getAttState(req.user.id));
});
app.post("/api/attendance/scan", ensureAuth, async (req, res) => {
    if (Math.random() < CONFIG.FP_FAIL_RATE) return res.json({ success: false });
    const name = await cyName(req.user.id);
    let st = await AttStatus.findOne({ uid: req.user.id });
    if (!st) st = new AttStatus({ uid: req.user.id });
    const now = new Date();
    const next = st.status === "in" ? "out" : "in";
    st.status = next; st.name = name; st.updatedAt = now;
    if (next === "in") st.lastCheckInAt = now; else st.lastCheckOutAt = now;
    await st.save();
    await AttLog.create({ uid: req.user.id, name, type: next, at: now });
    if (next === "in") await endLeaveOnAttendance(req.user.id).catch(e => console.error("❌ فشل إنهاء الإجازة عند الحضور:", e.message));
    if (next === "out") {
        // طلع => يطلع من أي تردد هو فيه
        for (const n of Array.from(offLive.keys())) {
            if (offIsFreq(n) && offLive.get(n) && offLive.get(n).has(req.user.id)) { offSendTo(req.user.id, { t: "kicked", n }); offRemove(req.user.id, n); }
        }
    }
    res.json({ success: true, status: next, at: now });
});
// بوابة: ما يسجل مخالفة/تقرير ولا يدخل تردد إلا بعد تسجيل الحضور
const ATT_GATED = [/^\/violations\/submit$/, /^\/reports\/submit$/, /^\/mp\/reports\/submit$/, /^\/officers\/rooms\/91\d\/join$/];
async function attendanceGate(req, res, next) {
    try {
        if (req.method !== "POST" || !req.user) return next();
        if (!ATT_GATED.some(r => r.test(req.path))) return next();
        if (!attRequired(req.user.id)) return next();
        const st = await getAttState(req.user.id);
        if (st.status === "in") return next();
        return res.status(403).json({ error: "🖐️ لازم تسجّل دخولك بالبصمة أول", needAttendance: true });
    } catch (e) { return next(); }
}

const ATT_TZ_MS = 3 * 60 * 60 * 1000;
const ATT_DAY_MS = 24 * 60 * 60 * 1000;
const ATT_SESSION_CAP = 12 * 60 * 60 * 1000;
function attDayStart(d) {
    const t = (d || new Date()).getTime();
    return new Date(Math.floor((t + ATT_TZ_MS) / ATT_DAY_MS) * ATT_DAY_MS - ATT_TZ_MS);
}
function attClip(a, b, from, to) {
    const s = Math.max(a, from), e = Math.min(b, to);
    return e > s ? e - s : 0;
}
function attCalcMs(logs, from, to) {
    let ms = 0, open = null;
    for (const l of logs) {
        const t = l.at.getTime();
        if (l.type === "in") open = t;
        else if (l.type === "out" && open !== null) {
            ms += attClip(open, Math.min(t, open + ATT_SESSION_CAP), from, to);
            open = null;
        }
    }
    if (open !== null) ms += attClip(open, Math.min(to, open + ATT_SESSION_CAP), from, to);
    return Math.floor(ms / 60000) * 60000;
}
function attGroup(logs) {
    logs.sort((a, b) => a.at - b.at);
    const m = new Map();
    for (const l of logs) {
        let a = m.get(l.uid);
        if (!a) { a = []; m.set(l.uid, a); }
        a.push(l);
    }
    return m;
}
async function attPeople(uids) {
    const out = new Map();
    if (!uids.length) return out;
    const [ps, accs] = await Promise.all([
        Personnel.find({ discord: { $in: uids } }, { discord: 1, registeredName: 1, unit: 1, rank: 1, sector: 1, discordTag: 1 }).maxTimeMS(10000).lean(),
        Account.find({ uid: { $in: uids } }, { uid: 1, fullName: 1, sector: 1 }).maxTimeMS(10000).lean(),
    ]);
    const pm = new Map(ps.map(p => [p.discord, p]));
    const am = new Map(accs.map(a => [a.uid, a]));
    for (const uid of uids) {
        const p = pm.get(uid) || {}, a = am.get(uid) || {};
        const key = a.sector || p.sector || null;
        out.set(uid, {
            name: p.registeredName || a.fullName || p.discordTag || null,
            unit: p.unit || null,
            rank: p.rank || null,
            sectorLabel: key ? (CONFIG.SECTORS[key] || null) : null,
        });
    }
    return out;
}
// ── عرض التحضير: قائد القطاع/مسؤول التحضير = قطاعه كامل | الشرطة العسكرية = كل القطاعات (غياب اليوم فقط) ──
app.get("/api/att-view", ensureAttViewer, async (req, res) => {
    try {
        const sc = req.attScope;
        const now = new Date(), ds = attDayStart(now);
        const fullSectors = sc.absentTodayOnly && !req.attScope.sectors.length ? [] : sc.sectors;
        const out = { sectors: [], absentToday: [], absentOnly: sc.absentTodayOnly && !fullSectors.length };
        if (fullSectors.length) {
            const accs = await Account.find({ status: "approved", sector: { $in: fullSectors } }, { uid: 1, sector: 1, fullName: 1 }).limit(3000).maxTimeMS(10000).lean();
            const uids = accs.map(a => a.uid);
            const [people, sts, logs] = await Promise.all([
                attPeople(uids),
                AttStatus.find({ uid: { $in: uids } }).limit(3000).maxTimeMS(10000).lean(),
                AttLog.find({ uid: { $in: uids }, at: { $gte: new Date(ds.getTime() - ATT_SESSION_CAP) } }, { uid: 1, type: 1, at: 1 }).limit(60000).maxTimeMS(10000).lean(),
            ]);
            const sm = new Map(sts.map(x => [x.uid, x]));
            const byUid = attGroup(logs);
            for (const key of fullSectors) {
                const members = accs.filter(a => a.sector === key).map(a => {
                    const pe = people.get(a.uid) || {}, st = sm.get(a.uid), lg = byUid.get(a.uid) || [];
                    return {
                        uid: a.uid, name: pe.name || a.fullName || a.uid, unit: pe.unit || null, rank: pe.rank || null,
                        status: st && st.status === "in" ? "in" : "out",
                        lastCheckInAt: st ? st.lastCheckInAt : null, lastCheckOutAt: st ? st.lastCheckOutAt : null,
                        todayIn: lg.filter(l => l.type === "in" && l.at >= ds).length,
                        todayMs: attCalcMs(lg, ds.getTime(), now.getTime()),
                    };
                }).sort((a, b) => (a.status === b.status ? String(a.name).localeCompare(String(b.name), "ar") : a.status === "in" ? -1 : 1));
                out.sectors.push({ key, label: CONFIG.SECTORS[key], present: members.filter(m => m.status === "in").length, members });
            }
        }
        // غياب اليوم (آخر استلام اليوم): للشرطة كل القطاعات، وللقادة قطاعاتهم
        const absKeys = sc.absentTodayOnly ? Object.keys(CONFIG.SECTORS) : fullSectors;
        const rows = await RecRow.find({ dayKey: { $gte: ds.getTime() }, kind: "absent", removedAt: null, sectorKey: { $in: absKeys } }).sort({ sectorKey: 1, name: 1 }).limit(2000).maxTimeMS(10000).lean();
        out.absentToday = rows.map(r => ({ uid: r.uid, name: r.name, unit: r.unit, rank: r.rank, sector: r.sector, excuseStatus: r.excuseStatus }));
        res.json(out);
    } catch (e) {
        console.error("❌ att-view:", e.message);
        res.status(500).json({ error: "تعذر تحميل التحضير، حاول مرة ثانية" });
    }
});
app.get("/api/senior/att/members", ensureSeniorAdmin, async (req, res) => {
    const now = new Date(), ds = attDayStart(now);
    const sts = await AttStatus.find({}).sort({ updatedAt: -1 }).limit(500).maxTimeMS(10000).lean();
    const uids = sts.map(s => s.uid);
    const [people, logs] = await Promise.all([
        attPeople(uids),
        AttLog.find({ at: { $gte: new Date(ds.getTime() - ATT_SESSION_CAP) } }, { uid: 1, type: 1, at: 1 }).limit(60000).maxTimeMS(10000).lean(),
    ]);
    const byUid = attGroup(logs);
    const list = sts.map(s => {
        const p = people.get(s.uid) || {};
        const lg = byUid.get(s.uid) || [];
        return {
            uid: s.uid,
            name: p.name || s.name || s.uid,
            unit: p.unit || null,
            rank: p.rank || null,
            sector: p.sectorLabel || null,
            status: s.status === "in" ? "in" : "out",
            lastCheckInAt: s.lastCheckInAt,
            lastCheckOutAt: s.lastCheckOutAt,
            todayIn: lg.filter(l => l.type === "in" && l.at >= ds).length,
            todayMs: attCalcMs(lg, ds.getTime(), now.getTime()),
        };
    });
    list.sort((a, b) => (a.status === b.status ? 0 : a.status === "in" ? -1 : 1));
    res.json({ list, present: list.filter(x => x.status === "in").length, maxHours: (await getAttCfg()).maxHours });
});
app.post("/api/senior/att/members/:uid/force/:type", ensureSeniorAdmin, async (req, res) => {
    const uid = String(req.params.uid || ""), type = req.params.type;
    if (!uid || !["in", "out"].includes(type)) return res.status(400).json({ error: "نوع غير صحيح" });
    let st = await AttStatus.findOne({ uid });
    if (!st) st = new AttStatus({ uid });
    if (!st.isNew && st.status === type) return res.json({ ok: true, same: true });
    const name = await cyName(uid);
    const now = new Date();
    st.status = type; st.name = name; st.updatedAt = now;
    if (type === "in") st.lastCheckInAt = now; else st.lastCheckOutAt = now;
    await st.save();
    await AttLog.create({ uid, name, type, at: now, by: req.user.id });
    if (type === "in") await endLeaveOnAttendance(uid).catch(e => console.error("❌ فشل إنهاء الإجازة عند الحضور:", e.message));
    if (type === "out") {
        for (const n of Array.from(offLive.keys())) {
            if (offIsFreq(n) && offLive.get(n) && offLive.get(n).has(uid)) { offSendTo(uid, { t: "kicked", n }); offRemove(uid, n); }
        }
    }
    await logEvent({ action: type === "in" ? "تحضير يدوي بالبصمة" : "انصراف يدوي بالبصمة", discordId: uid, actorId: req.user.id, actorTag: req.user.username, details: name });
    res.json({ ok: true });
});
app.get("/api/senior/att/member/:uid", ensureSeniorAdmin, async (req, res) => {
    const uid = String(req.params.uid || "");
    const now = new Date(), ds = attDayStart(now);
    const from = new Date(ds.getTime() - 6 * ATT_DAY_MS);
    const logs = await AttLog.find({ uid, at: { $gte: new Date(from.getTime() - ATT_SESSION_CAP) } }, { type: 1, at: 1, by: 1, uid: 1 }).maxTimeMS(10000).lean();
    logs.sort((a, b) => a.at - b.at);
    const days = [];
    for (let i = 6; i >= 0; i--) {
        const s = ds.getTime() - i * ATT_DAY_MS;
        days.push({ start: new Date(s), ms: attCalcMs(logs, s, Math.min(s + ATT_DAY_MS, now.getTime())) });
    }
    const weekMs = days.reduce((t, d) => t + d.ms, 0);
    const recent = logs.filter(l => l.at >= from).slice(-40).reverse().map(l => ({ type: l.type, at: l.at, forced: !!l.by && l.by !== "auto", auto: l.by === "auto" }));
    res.json({ weekMs, days, recent });
});
app.get("/api/senior/att/hours", ensureSeniorAdmin, async (req, res) => {
    const period = ["day", "week", "month"].includes(req.query.period) ? req.query.period : "week";
    const now = new Date(), ds = attDayStart(now);
    const from = period === "day" ? ds : new Date(now.getTime() - (period === "week" ? 7 : 30) * ATT_DAY_MS);
    const logs = await AttLog.find({ at: { $gte: new Date(from.getTime() - ATT_SESSION_CAP) } }, { uid: 1, type: 1, at: 1 }).limit(60000).maxTimeMS(10000).lean();
    const rows = [];
    let totalMs = 0;
    for (const [uid, lg] of attGroup(logs)) {
        const ms = attCalcMs(lg, from.getTime(), now.getTime());
        if (ms <= 0) continue;
        totalMs += ms;
        const dayKeys = new Set(lg.filter(l => l.type === "in" && l.at >= from).map(l => Math.floor((l.at.getTime() + ATT_TZ_MS) / ATT_DAY_MS)));
        rows.push({ uid, ms, days: dayKeys.size });
    }
    rows.sort((a, b) => b.ms - a.ms);
    const top = rows.slice(0, 100);
    const people = await attPeople(top.map(r => r.uid));
    const list = top.map(r => {
        const p = people.get(r.uid) || {};
        return { uid: r.uid, name: p.name || r.uid, unit: p.unit || null, rank: p.rank || null, sector: p.sectorLabel || null, ms: r.ms, days: r.days };
    });
    res.json({ period, list, totalMs, count: rows.length });
});
app.get("/api/senior/att/absent", ensureSeniorAdmin, async (req, res) => {
    const d = parseInt(req.query.days, 10);
    const days = [1, 3, 7, 14].includes(d) ? d : 3;
    const now = new Date();
    if (days === 1) {
        const rd = await RecDay.findOne({ openedAt: { $gte: attDayStart(now) }, status: { $ne: "open" } }).sort({ openedAt: -1 }).lean();
        if (rd) {
            const rows = await RecRow.find({ dayKey: rd.dayKey }).limit(5000).maxTimeMS(10000).lean();
            const slim = r => ({ uid: r.uid, name: r.name, unit: r.unit, rank: r.rank, sector: r.sector, deducted: r.deducted, refunded: r.refunded, excuseStatus: r.excuseStatus, onLeave: r.kind === "leave", lastCheckInAt: null });
            const byName = (a, b) => String(a.name || "").localeCompare(String(b.name || ""), "ar");
            const attended = rows.filter(r => r.kind === "attended").map(slim).sort(byName);
            const absentRows = rows.filter(r => r.kind === "absent").map(slim).sort(byName);
            const leaveRows = rows.filter(r => r.kind === "leave").map(slim).sort(byName);
            return res.json({
                days, total: rows.length, absentCount: absentRows.length,
                reception: { dayKey: rd.dayKey, openedAt: rd.openedAt, openedByName: rd.openedByName, closedAt: rd.closedAt || null, closedByName: rd.closedByName || null, attendedCount: attended.length, absentCount: absentRows.length, leaveCount: leaveRows.length },
                attended, list: absentRows.concat(leaveRows),
            });
        }
    }
    const since = new Date(attDayStart(now).getTime() - (days - 1) * ATT_DAY_MS);
    const [accs, ps, sts, leaves] = await Promise.all([
        Account.find({ status: "approved" }, { uid: 1, fullName: 1, sector: 1, isSenior: 1, isOwner: 1, tempSenior: 1 }).limit(5000).maxTimeMS(10000).lean(),
        Personnel.find({}, { discord: 1, registeredName: 1, unit: 1, rank: 1, sector: 1, isDismissed: 1 }).limit(5000).maxTimeMS(10000).lean(),
        AttStatus.find({}, { uid: 1, status: 1, lastCheckInAt: 1 }).limit(5000).maxTimeMS(10000).lean(),
        LeaveRequest.find({ status: "approved" }, { discord: 1, endDate: 1 }).limit(5000).maxTimeMS(10000).lean(),
    ]);
    const pm = new Map(ps.map(p => [p.discord, p]));
    const sm = new Map(sts.map(s => [s.uid, s]));
    const lv = new Set(leaves.filter(l => !l.endDate || l.endDate > now).map(l => l.discord));
    const universe = accs.filter(a => !a.isSenior && !a.isOwner && !a.tempSenior && !isSeniorAdmin(a.uid) && !(pm.get(a.uid) || {}).isDismissed);
    const list = [];
    for (const a of universe) {
        const st = sm.get(a.uid);
        if (st && (st.status === "in" || (st.lastCheckInAt && st.lastCheckInAt >= since))) continue;
        const p = pm.get(a.uid) || {};
        const key = a.sector || p.sector || null;
        list.push({
            uid: a.uid,
            name: p.registeredName || a.fullName || a.uid,
            unit: p.unit || null,
            rank: p.rank || null,
            sector: key ? (CONFIG.SECTORS[key] || null) : null,
            lastCheckInAt: st ? st.lastCheckInAt : null,
            onLeave: lv.has(a.uid),
        });
    }
    list.sort((x, y) => (x.lastCheckInAt ? x.lastCheckInAt.getTime() : 0) - (y.lastCheckInAt ? y.lastCheckInAt.getTime() : 0));
    res.json({ days, total: universe.length, absentCount: list.length, list: list.slice(0, 400) });
});
app.get("/api/senior/att/sectors", ensureSeniorAdmin, async (req, res) => {
    const now = new Date(), ds = attDayStart(now);
    const weekFrom = new Date(ds.getTime() - 6 * ATT_DAY_MS);
    const [accs, sts, logs, leaves] = await Promise.all([
        Account.find({ status: "approved" }, { uid: 1, sector: 1, isSenior: 1, isOwner: 1, tempSenior: 1 }).limit(5000).maxTimeMS(10000).lean(),
        AttStatus.find({}, { uid: 1, status: 1, lastCheckInAt: 1 }).limit(5000).maxTimeMS(10000).lean(),
        AttLog.find({ type: "in", at: { $gte: weekFrom } }, { uid: 1, at: 1 }).limit(60000).maxTimeMS(10000).lean(),
        LeaveRequest.find({ status: "approved" }, { discord: 1, endDate: 1 }).limit(5000).maxTimeMS(10000).lean(),
    ]);
    const sm = new Map(sts.map(s => [s.uid, s]));
    const lv = new Set(leaves.filter(l => !l.endDate || l.endDate > now).map(l => l.discord));
    const keys = Object.keys(CONFIG.SECTORS).concat(["none"]);
    const rows = new Map(keys.map(k => [k, { key: k, label: k === "none" ? "بدون قطاع" : CONFIG.SECTORS[k], total: 0, present: 0, today: 0, leave: 0 }]));
    let total = 0, presentNow = 0, todayTotal = 0;
    for (const a of accs) {
        if (a.isSenior || a.isOwner || a.tempSenior || isSeniorAdmin(a.uid)) continue;
        const r = rows.get(a.sector && rows.has(a.sector) ? a.sector : "none");
        const st = sm.get(a.uid);
        const isIn = !!(st && st.status === "in");
        const cameToday = !!(st && (isIn || (st.lastCheckInAt && st.lastCheckInAt >= ds)));
        r.total++; total++;
        if (isIn) { r.present++; presentNow++; }
        if (cameToday) { r.today++; todayTotal++; }
        if (lv.has(a.uid)) r.leave++;
    }
    const daily = [];
    for (let i = 6; i >= 0; i--) {
        const s = ds.getTime() - i * ATT_DAY_MS, e = s + ATT_DAY_MS;
        const u = new Set();
        for (const l of logs) { const t = l.at.getTime(); if (t >= s && t < e) u.add(l.uid); }
        daily.push({ start: new Date(s), count: u.size });
    }
    res.json({ total, presentNow, todayTotal, daily, sectors: Array.from(rows.values()).filter(r => r.total > 0) });
});

// ---------- حماية الحضور: تجاوز مدة الحضور (ملاحظة تلقائية + تصعيد للقيادة عند التكرار) ----------
const ATT_CFG_DEFAULT = { enabled: true, maxHours: 8, autoCheckout: true, repeatThreshold: 2, notifyMember: true, discordAlert: true };
async function getAttCfg() {
    const s = await getSettings();
    return Object.assign({}, ATT_CFG_DEFAULT, (s && s.attConfig) || {});
}
const AttViolationSchema = new mongoose.Schema({
    uid: String, name: String,
    checkInAt: Date, hoursAway: Number, occurrence: Number, maxHours: Number,
    status: { type: String, enum: ["note", "pending", "deciding", "warned", "penalized", "dismissed"], default: "note" },
    autoCheckedOut: { type: Boolean, default: false },
    decisionBy: String, decisionByName: String, decisionAt: Date, decisionLabel: String, decisionReason: String,
    createdAt: { type: Date, default: Date.now },
});
AttViolationSchema.index({ uid: 1, checkInAt: 1 }, { unique: true });
AttViolationSchema.index({ status: 1, createdAt: -1 });
const AttViolation = mongoose.model("AttViolation", AttViolationSchema);

// انصراف (تلقائي أو بواسطة الإدارة) مع إخراجه من أي تردد
async function attForceOut(uid, by) {
    const now = new Date();
    const st = await AttStatus.findOneAndUpdate({ uid, status: "in" }, { $set: { status: "out", lastCheckOutAt: now, updatedAt: now } }, { new: true });
    if (!st) return false;
    await AttLog.create({ uid, name: st.name || uid, type: "out", at: now, by });
    for (const n of Array.from(offLive.keys())) {
        if (offIsFreq(n) && offLive.get(n) && offLive.get(n).has(uid)) { offSendTo(uid, { t: "kicked", n }); offRemove(uid, n); }
    }
    return true;
}

// تنبيه القيادة (القيادة العليا + كبار المسؤولين) لما أحد يكرر التجاوز
async function attNotifyLeadership(v) {
    const cfg = await getAttCfg();
    const settings = await getSettings();
    const ids = new Set((settings.highCommand || []).map(m => m.id).concat(Array.from(seniorUids)));
    ids.delete(v.uid);
    if (!ids.size) return;
    const text = "🚨 تكرار تجاوز الحضور\nالعضو: " + v.name + "\nبقي حاضر " + v.hoursAway + " ساعة بدون انصراف (المرة رقم " + v.occurrence + ")\nحدد تحذير أو عقوبة من تاب «تجاوزات الحضور».";
    sseBroadcast("hcalert", { t: Date.now(), att: true }, c => !!c.uid && ids.has(c.uid));
    for (const id of ids) {
        pushNoticeTo(id, text, "auto", "🤖 نظام الحضور").catch(() => {});
        pushUid(id, { title: CONFIG.SITE_NAME, body: "🚨 تكرار تجاوز حضور — " + v.name, tag: "att-over-" + v._id, ttl: 86400 }).catch(() => {});
    }
    if (cfg.discordAlert && botReady) {
        const embed = new EmbedBuilder().setTitle("🚨 تكرار تجاوز الحضور").setColor(0xef4444).addFields(
            { name: "العضو", value: v.name || "-", inline: true },
            { name: "مدة الحضور", value: v.hoursAway + " ساعة", inline: true },
            { name: "المرة", value: String(v.occurrence), inline: true },
            { name: "المطلوب", value: "حدد تحذير أو عقوبة من الموقع (تاب تجاوزات الحضور)", inline: false },
        ).setTimestamp(new Date());
        for (const id of ids) { try { const u = await client.users.fetch(id); await u.send({ embeds: [embed] }); } catch (e) {} }
    }
}

async function attHandleOver(st, cfg) {
    if (!st.lastCheckInAt || isSeniorAdmin(st.uid)) return;
    if (await AttViolation.exists({ uid: st.uid, checkInAt: st.lastCheckInAt })) return;
    const occurrence = (await AttViolation.countDocuments({ uid: st.uid })) + 1;
    const repeated = occurrence >= cfg.repeatThreshold;
    const name = st.name || await cyName(st.uid);
    const hours = Math.round((Date.now() - st.lastCheckInAt.getTime()) / 360000) / 10;
    let v;
    try {
        v = await AttViolation.create({
            uid: st.uid, name, checkInAt: st.lastCheckInAt, hoursAway: hours, occurrence, maxHours: cfg.maxHours,
            status: repeated ? "pending" : "note", autoCheckedOut: !!cfg.autoCheckout,
        });
    } catch (e) { return; }
    if (cfg.autoCheckout) await attForceOut(st.uid, "auto");
    const noteText = "⏱️ ملاحظة تلقائية: بقي حاضر " + hours + " ساعة بدون انصراف (الحد " + cfg.maxHours + " ساعات)" + (cfg.autoCheckout ? " — انسجّل انصرافه تلقائياً" : "") + " — المرة رقم " + occurrence + ".";
    await Personnel.updateOne({ discord: st.uid }, { $push: { notes: { text: noteText, addedBy: "auto", addedByTag: "🤖 نظام الحضور" } } }).catch(() => {});
    if (cfg.notifyMember) {
        const msg = "⏱️ انسجّلت عليك ملاحظة: بقيت حاضر " + hours + " ساعة بدون انصراف (الحد " + cfg.maxHours + " ساعات)." + (repeated ? " الأمر تكرر وانرفع للقيادة." : " لا تنسى تسجّل انصرافك.");
        pushNoticeTo(st.uid, msg, "auto", "🤖 نظام الحضور").catch(() => {});
        pushUid(st.uid, { title: CONFIG.SITE_NAME, body: "⏱️ ملاحظة: نسيت تسجّل انصرافك", tag: "att-note", ttl: 86400 }).catch(() => {});
    }
    await logEvent({ action: repeated ? "تجاوز حضور متكرر (للقيادة)" : "ملاحظة تجاوز حضور تلقائية", discordId: st.uid, actorId: "auto", actorTag: "🤖 نظام الحضور", details: name + " — " + hours + " ساعة (المرة " + occurrence + ")" });
    if (repeated) await attNotifyLeadership(v);
}

let attWatchBusy = false;
async function attOverCheck() {
    if (attWatchBusy) return;
    attWatchBusy = true;
    try {
        const cfg = await getAttCfg();
        if (!cfg.enabled) return;
        const limit = new Date(Date.now() - cfg.maxHours * 3600000);
        const over = await AttStatus.find({ status: "in", lastCheckInAt: { $lte: limit } }).limit(300).lean();
        for (const st of over) {
            try { await attHandleOver(st, cfg); } catch (e) { console.error("❌ فشل معالجة تجاوز الحضور:", e.message); }
        }
    } catch (e) { console.error("❌ فشل فحص تجاوز الحضور:", e.message); }
    finally { attWatchBusy = false; }
}
setInterval(() => { attOverCheck().catch(() => {}); }, 5 * 60 * 1000);
setTimeout(() => { attOverCheck().catch(() => {}); }, 30000);

app.get("/api/senior/att/config", ensureSeniorAdmin, async (req, res) => {
    res.json({ config: await getAttCfg() });
});
app.post("/api/senior/att/config", ensureSeniorAdmin, async (req, res) => {
    const b = req.body || {};
    const cur = await getAttCfg();
    const num = (v, lo, hi, d) => { const n = parseInt(v, 10); return isNaN(n) ? d : Math.max(lo, Math.min(hi, n)); };
    const bool = (v, d) => (v === undefined ? d : !!v);
    const cfg = {
        enabled: bool(b.enabled, cur.enabled),
        maxHours: num(b.maxHours, 2, 24, cur.maxHours),
        autoCheckout: bool(b.autoCheckout, cur.autoCheckout),
        repeatThreshold: num(b.repeatThreshold, 1, 10, cur.repeatThreshold),
        notifyMember: bool(b.notifyMember, cur.notifyMember),
        discordAlert: bool(b.discordAlert, cur.discordAlert),
    };
    const s = await getSettings();
    s.attConfig = cfg;
    s.markModified("attConfig");
    await s.save();
    await logEvent({ action: "تعديل إعدادات الحضور", actorId: req.user.id, actorTag: req.user.username, details: "الحد " + cfg.maxHours + " ساعات — " + (cfg.enabled ? "مفعّل" : "متوقف") + " — تصعيد من المرة " + cfg.repeatThreshold });
    res.json({ ok: true, config: cfg });
});

// زر: ينصرف الكل يدوياً (الحاضرين كلهم، أو اللي نسوا الانصراف بس)
app.post("/api/senior/att/checkout-all", ensureSeniorAdmin, async (req, res) => {
    const scope = (req.body && req.body.scope) === "stale" ? "stale" : "in";
    const cfg = await getAttCfg();
    if (scope === "stale") await attOverCheck();
    const q = { status: "in" };
    if (scope === "stale") q.lastCheckInAt = { $lte: new Date(Date.now() - cfg.maxHours * 3600000) };
    const list = await AttStatus.find(q, { uid: 1 }).limit(5000).lean();
    let count = 0;
    for (const x of list) { if (await attForceOut(x.uid, req.user.id)) count++; }
    await logEvent({ action: "انصراف جماعي يدوي", actorId: req.user.id, actorTag: req.user.username, details: (scope === "stale" ? "اللي نسوا الانصراف" : "كل الحاضرين") + " — " + count });
    res.json({ ok: true, count });
});

// تجاوزات الحضور: القيادة العليا + كبار المسؤولين
app.get("/api/hc/att-violations", ensureHighCommand, async (req, res) => {
    const f = String(req.query.filter || "pending");
    const q = f === "pending" ? { status: { $in: ["pending", "deciding"] } }
        : f === "notes" ? { status: "note" }
        : f === "done" ? { status: { $in: ["warned", "penalized", "dismissed"] } } : {};
    const [list, pendingCount] = await Promise.all([
        AttViolation.find(q).sort({ createdAt: -1 }).limit(200).lean(),
        AttViolation.countDocuments({ status: "pending" }),
    ]);
    const penalties = (req.settings.warningPenalties || []).map(p => ({ id: p.id, label: p.label }));
    res.json({ list, pendingCount, penalties });
});
app.post("/api/hc/att-violations/:id/decide", ensureHighCommand, async (req, res) => {
    const b = req.body || {};
    const action = b.action;
    if (!["warning", "penalty", "dismiss"].includes(action)) return res.status(400).json({ error: "قرار غير معروف" });
    if (!mongoose.Types.ObjectId.isValid(req.params.id)) return res.status(404).json({ error: "غير موجود" });
    let pen = null;
    if (action === "penalty") {
        pen = (req.settings.warningPenalties || []).find(x => x.id === b.penaltyId);
        if (!pen) return res.status(400).json({ error: "اختر العقوبة" });
    }
    const v = await AttViolation.findOneAndUpdate({ _id: req.params.id, status: "pending" }, { $set: { status: "deciding" } }, { new: true });
    if (!v) return res.status(409).json({ error: "تم اتخاذ قرار على هذي الحالة من قبل" });
    const byName = await cyName(req.user.id);
    const extra = String(b.reason || "").trim().slice(0, 300);
    const baseReason = "تكرار البقاء حاضر أكثر من " + (v.maxHours || 8) + " ساعات بدون انصراف (المرة رقم " + v.occurrence + ")" + (extra ? " — " + extra : "");
    try {
        let label, status;
        if (action === "warning") {
            const r = await issueWarning({ targetDiscord: v.uid, kind: "warning", reason: baseReason, actorId: req.user.id, actorTag: req.user.username });
            status = "warned"; label = r.dismissed ? "تحذير (انفصل تلقائياً)" : "تحذير";
        } else if (action === "penalty") {
            const p = await Personnel.findOne({ discord: v.uid });
            if (!p) throw new Error("العضو غير موجود");
            applyPenaltyEffect(p, pen);
            p.warnings.push({ kind: "notice", reason: "⚖️ عقوبة من القيادة: " + pen.label + " — السبب: " + baseReason, issuedBy: req.user.id, issuedByTag: req.user.username, penaltyType: pen.type, penaltyLabel: pen.label });
            await p.save();
            status = "penalized"; label = pen.label;
            await logEvent({ action: "عقوبة تجاوز حضور", discordId: p.discord, discordTag: p.discordTag, actorId: req.user.id, actorTag: req.user.username, details: p.registeredName + " — " + pen.label });
        } else {
            status = "dismissed"; label = "حفظ بدون إجراء";
        }
        await AttViolation.updateOne({ _id: v._id }, { $set: { status, decisionBy: req.user.id, decisionByName: byName, decisionAt: new Date(), decisionLabel: label, decisionReason: extra || null } });
        res.json({ ok: true });
    } catch (e) {
        await AttViolation.updateOne({ _id: v._id, status: "deciding" }, { $set: { status: "pending" } });
        res.status(400).json({ error: e.message });
    }
});


const RecDay = mongoose.model("RecDay", new mongoose.Schema({
    dayKey: { type: Number, unique: true }, openedAt: Date, openedBy: String, openedByName: String,
    status: { type: String, default: "closed" }, // open = الاستلام مفتوح الحين • closed = انسكّر وانحسبت الغيابات
    closedAt: Date, closedBy: String, closedByName: String,
}));
const RecRowSchema = new mongoose.Schema({
    dayKey: { type: Number, index: true }, uid: String, name: String, unit: String, rank: String,
    sector: String, sectorKey: String, kind: String,
    gained: { type: Number, default: 0 }, deducted: { type: Number, default: 0 }, refunded: { type: Number, default: 0 },
    excuseStatus: { type: String, default: "none" }, excuseId: { type: String, default: null }, openedAt: Date,
    removedAt: Date, removedBy: String, removedByName: String,
    // حماية الاستلام: watch = ينتظر مؤقت الـ 8 ساعات • ok = سجّل مخالفة صالحة • absent = انقلب غياب • exempt = معفى (موقوف/مفصول/بطاقة ملغاة)
    protStatus: { type: String, default: null }, protDeadline: Date, protCheckedAt: Date,
});
RecRowSchema.index({ dayKey: 1, uid: 1 }, { unique: true });
RecRowSchema.index({ protStatus: 1, protDeadline: 1 });
const RecRow = mongoose.model("RecRow", RecRowSchema);
const AbsenceExcuseSchema = new mongoose.Schema({
    rowId: String, dayKey: Number, uid: String, name: String, unit: String, rank: String, sector: String, sectorKey: String,
    type: { type: String, enum: ["medical", "nonmedical"], default: "nonmedical" },
    reason: String, proof: { type: String, default: null }, proofChannelId: { type: String, default: null }, proofMessageId: { type: String, default: null }, hasProof: { type: Boolean, default: false },
    status: { type: String, enum: ["pending", "deciding", "accepted", "rejected"], default: "pending" },
    rejectReason: { type: String, default: null }, absenceAt: Date,
    oathText: { type: String, default: null },
    audio: { type: Buffer, default: undefined }, audioChannelId: { type: String, default: null }, audioMessageId: { type: String, default: null },
    audioMime: { type: String, default: null }, audioDuration: { type: Number, default: null }, audioWave: { type: String, default: null }, hasAudio: { type: Boolean, default: false },
    decidedBy: String, decidedByName: String, decidedAt: Date, refunded: { type: Number, default: 0 },
    createdAt: { type: Date, default: Date.now },
});
AbsenceExcuseSchema.index({ uid: 1, createdAt: -1 });
const AbsenceExcuse = mongoose.model("AbsenceExcuse", AbsenceExcuseSchema);

const EXCUSE_WINDOW_DAYS = 14;
const EXCUSE_TYPE_LABEL = { medical: "طبي", nonmedical: "بدون طبي" };

// فتح الاستلام: بس يسجّل إنه مفتوح (ما يحسب غياب الحين)
async function openReceptionDay(openerId, openerName) {
    const now = new Date();
    const dayKey = now.getTime(); // كل استلام له مفتاح خاص (يتكرر باليوم أكثر من مرة)
    try { await RecDay.create({ dayKey, openedAt: now, openedBy: openerId, openedByName: openerName, status: "open" }); }
    catch (e) { return null; }
    return { dayKey, openedAt: now };
}

// حالة الاستلام اليوم (مفتوح الحين؟ / انتهى اليوم؟) — ولو في استلام قديم نسوا يسكرونه ينسكّر بدون حساب
async function getReceptionState() {
    const now = new Date();
    await RecDay.updateMany({ status: "open", openedAt: { $lt: attDayStart(now) } }, { $set: { status: "closed", closedAt: now, closedByName: "تلقائي" } }).catch(() => {});
    const rd = await RecDay.findOne({ status: "open" }, { openedAt: 1, openedByName: 1 }).sort({ openedAt: -1 }).lean();
    return { open: rd ? { openedAt: rd.openedAt, openedByName: rd.openedByName } : null };
}

// إغلاق الاستلام: هنا بس يحسب الحضور والغياب وقتها
async function closeReceptionDay(closerId, closerName) {
    const now = new Date();
    const rd = await RecDay.findOneAndUpdate(
        { status: "open" },
        { $set: { status: "closed", closedAt: now, closedBy: closerId, closedByName: closerName } },
        { new: true, sort: { openedAt: -1 } }
    );
    if (!rd) return null;
    const dayKey = rd.dayKey;
    const settings = await getSettings();
    const [accs, ps, sts, leaves] = await Promise.all([
        Account.find({ status: "approved" }, { uid: 1, sector: 1, isSenior: 1, isOwner: 1, tempSenior: 1 }).limit(5000).maxTimeMS(10000).lean(),
        Personnel.find({}, { discord: 1, registeredName: 1, unit: 1, rank: 1, sector: 1, points: 1, isDismissed: 1, isBlocked: 1 }).limit(5000).maxTimeMS(10000).lean(),
        AttStatus.find({}, { uid: 1, status: 1 }).limit(5000).maxTimeMS(10000).lean(),
        LeaveRequest.find({ status: "approved" }, { discord: 1, endDate: 1 }).limit(5000).maxTimeMS(10000).lean(),
    ]);
    const pm = new Map(ps.map(p => [p.discord, p]));
    const sm = new Map(sts.map(s => [s.uid, s]));
    const lv = new Set(leaves.filter(l => !l.endDate || l.endDate > now).map(l => l.discord));
    // اللي حضر وقعد 15 دقيقة على الأقل بعد فتح الاستلام وسوا انصراف قبل الإغلاق = يحسب حاضر (مو غياب)
    const REC_MIN_STAY_MS = 15 * 60 * 1000;
    const stayed = new Set();
    try {
        const winS = new Date(rd.openedAt).getTime(), winE = now.getTime();
        const logs = await AttLog.find({ at: { $gte: new Date(winS - ATT_SESSION_CAP) } }, { uid: 1, type: 1, at: 1 }).sort({ at: 1 }).limit(60000).maxTimeMS(10000).lean();
        const cur = new Map();
        for (const l of logs) {
            const tt = new Date(l.at).getTime();
            if (l.type === "in") { if (!cur.has(l.uid)) cur.set(l.uid, tt); }
            else if (l.type === "out") {
                const s0 = cur.get(l.uid);
                if (s0 !== undefined) {
                    const ov = Math.min(tt, winE) - Math.max(s0, tt - ATT_SESSION_CAP, winS);
                    if (ov >= REC_MIN_STAY_MS) stayed.add(l.uid);
                    cur.delete(l.uid);
                }
            }
        }
    } catch (e) { console.error("❌ فشل حساب مدة بقاء الاستلام:", e.message); }
    // الاستلام مرة وحدة باليوم: اللي حضر استلام سابق اليوم ما ينحسب عليه غياب بهذا الاستلام (ولو حضر ياخذ نقطته عادي)
    const attendedEarlier = new Set();
    try {
        const earlier = await RecDay.find({ dayKey: { $ne: dayKey }, openedAt: { $gte: attDayStart(rd.openedAt), $lt: rd.openedAt } }, { dayKey: 1 }).lean();
        if (earlier.length) {
            const prev = await RecRow.find({ dayKey: { $in: earlier.map(e => e.dayKey) }, kind: "attended", removedAt: null }, { uid: 1 }).limit(20000).maxTimeMS(10000).lean();
            prev.forEach(r => attendedEarlier.add(r.uid));
        }
    } catch (e) { console.error("❌ فشل جلب حضور الاستلامات السابقة:", e.message); }
    const protDeadline = new Date(now.getTime() + REC_PROT_MS);
    const rows = [], ops = [];
    let attended = 0, absent = 0, leave = 0, skippedEarlier = 0;
    for (const a of accs) {
        if (a.isSenior || a.isOwner || a.tempSenior || isSeniorAdmin(a.uid) || isHighCommand(a.uid, settings)) continue;
        const p = pm.get(a.uid);
        if (!p || !p.registeredName || p.isDismissed || p.isBlocked) continue;
        const key = a.sector || p.sector || null;
        if (!p.unit || !key) continue;
        const st = sm.get(a.uid);
        const base = { dayKey, uid: a.uid, name: p.registeredName, unit: p.unit, rank: p.rank, sector: CONFIG.SECTORS[key] || null, sectorKey: key, openedAt: rd.openedAt };
        if ((st && st.status === "in") || stayed.has(a.uid)) {
            // اللي مسجّل حضور وقت انتهاء الاستلام يبدأ له مؤقت 8 ساعات (حماية: لازم يسجّل مخالفة صالحة)
            const watch = !!(st && st.status === "in");
            rows.push({ ...base, kind: "attended", gained: 1, ...(watch ? { protStatus: "watch", protDeadline } : {}) });
            ops.push({ updateOne: { filter: { discord: a.uid }, update: { $inc: { points: 1 } } } });
            attended++;
        } else if (attendedEarlier.has(a.uid)) {
            skippedEarlier++;   // حضر استلام سابق اليوم: هذا الاستلام ما يحسب عليه
        } else if (lv.has(a.uid)) {
            rows.push({ ...base, kind: "leave" });
            leave++;
        } else {
            const ded = 5; // خصم ثابت خمس نقاط حتى لو رصيده 0 أو 1 (يصير بالسالب)
            rows.push({ ...base, kind: "absent", deducted: ded, excuseStatus: "none" });
            if (ded) ops.push({ updateOne: { filter: { discord: a.uid }, update: { $inc: { points: -ded } } } });
            absent++;
        }
    }
    if (rows.length) await RecRow.insertMany(rows, { ordered: false }).catch(e => console.error("❌ فشل حفظ حضور الاستلام:", e.message));
    if (ops.length) await Personnel.bulkWrite(ops, { ordered: false }).catch(e => console.error("❌ فشل تحديث نقاط الاستلام:", e.message));
    (async () => {
        for (const r of rows) {
            if (r.kind !== "absent") continue;
            await pushUid(r.uid, { title: CONFIG.SITE_NAME, body: "غبت عن الاستلام" + (r.deducted ? " وانخصم عليك " + r.deducted + " نقطة" : "") + " — تقدر تقدم عذر من صفحة غياب بعذر", ttl: 3600, tag: "recabs" }).catch(() => {});
        }
    })();
    await logEvent({ action: "إغلاق استلام وحساب الغيابات", actorId: closerId, details: "حضروا " + attended + " (+1) • غابوا " + absent + " (-5) • إجازة " + leave + (skippedEarlier ? " • ما انحسب عليهم (حضروا استلام سابق اليوم) " + skippedEarlier : "") });
    return { attended, absent, leave };
}

// ═══ حماية الاستلام ═══
// اللي انحسب حاضر وهو مسجّل حضور وقت انتهاء الاستلام: يبدأ له مؤقت 8 ساعات.
// لو ما سجّل ولا مخالفة صالحة خلالها => ينقلب حضوره غياب (تنسحب نقطة الحضور وينخصم 5).
// المخالفة المرفوضة تعتبر كأنها ما انسجلت، والمعلّقة ننتظر قرارها.
const REC_PROT_MS = 8 * 60 * 60 * 1000;
let recProtBusy = false;
async function runRecProtection() {
    if (recProtBusy) return;
    recProtBusy = true;
    try {
        const now = new Date();
        const due = await RecRow.find({ kind: "attended", protStatus: "watch", protDeadline: { $lte: now }, removedAt: null }).limit(300).maxTimeMS(10000).lean();
        if (!due.length) return;
        const settings = await getSettings();
        if (settings.disableViolations) {   // تسجيل المخالفات مقفل: ما نظلم أحد، نأجّل ساعة
            await RecRow.updateMany({ _id: { $in: due.map(r => r._id) } }, { $set: { protDeadline: new Date(now.getTime() + 60 * 60 * 1000) } });
            return;
        }
        const uids = [...new Set(due.map(r => r.uid))];
        const since = new Date(Math.min(...due.map(r => new Date(r.openedAt).getTime())));
        const [vs, ps] = await Promise.all([
            Violation.find({ reporterDiscord: { $in: uids }, createdAt: { $gte: since } }, { reporterDiscord: 1, createdAt: 1, status: 1 }).limit(20000).maxTimeMS(10000).lean(),
            Personnel.find({ discord: { $in: uids } }, { discord: 1, isBlocked: 1, isDismissed: 1, cardRevoked: 1 }).maxTimeMS(10000).lean(),
        ]);
        const pm = new Map(ps.map(p => [p.discord, p]));
        const ops = [], flipped = [];
        for (const row of due) {
            const from = new Date(row.openedAt).getTime(), to = new Date(row.protDeadline).getTime();
            const mine = vs.filter(v => v.reporterDiscord === row.uid && new Date(v.createdAt).getTime() >= from && new Date(v.createdAt).getTime() <= to);
            if (mine.some(v => v.status !== "pending" && v.status !== "rejected")) {
                await RecRow.updateOne({ _id: row._id, protStatus: "watch" }, { $set: { protStatus: "ok", protCheckedAt: now } });
                continue;
            }
            if (mine.some(v => v.status === "pending")) {   // لسا ما انقرر عليها: ننتظر
                await RecRow.updateOne({ _id: row._id }, { $set: { protCheckedAt: now } });
                continue;
            }
            const p = pm.get(row.uid);
            if (!p || p.isBlocked || p.isDismissed || p.cardRevoked) {   // ما يقدر يسجّل مخالفات أصلاً: معفى
                await RecRow.updateOne({ _id: row._id, protStatus: "watch" }, { $set: { protStatus: "exempt", protCheckedAt: now } });
                continue;
            }
            const r0 = await RecRow.findOneAndUpdate(
                { _id: row._id, kind: "attended", protStatus: "watch", removedAt: null },
                { $set: { kind: "absent", gained: 0, deducted: 5, excuseStatus: "none", protStatus: "absent", protCheckedAt: now } }
            );
            if (!r0) continue;
            ops.push({ updateOne: { filter: { discord: row.uid }, update: { $inc: { points: -6 } } } });   // سحب نقطة الحضور + خصم 5
            flipped.push(row);
        }
        if (ops.length) await Personnel.bulkWrite(ops, { ordered: false }).catch(e => console.error("❌ فشل خصم حماية الاستلام:", e.message));
        for (const r of flipped) {
            await pushUid(r.uid, { title: CONFIG.SITE_NAME, body: "انحسب عليك غياب عن الاستلام: ما سجّلت أي مخالفة صالحة خلال 8 ساعات من انتهاءه (المرفوضة ما تنحسب). انسحبت نقطة الحضور وانخصم عليك 5 نقاط — تقدر تقدم عذر من صفحة غياب بعذر", ttl: 3600, tag: "recabs" }).catch(() => {});
        }
        if (flipped.length) await logEvent({ action: "حماية الاستلام: تحويل حضور لغياب", actorId: "auto", actorTag: "🤖 نظام حماية الاستلام", details: "انقلب غياب لعدم تسجيل مخالفة صالحة خلال 8 ساعات: " + flipped.map(r => r.name).join("، ") });
    } catch (e) { console.error("❌ حماية الاستلام:", e.message); }
    finally { recProtBusy = false; }
}
