app.post("/api/hc/excuses/:id/accept", ensureHighCommand, async (req, res) => {
    if (!mongoose.Types.ObjectId.isValid(req.params.id)) return res.status(404).json({ error: "غير موجود" });
    const ex = await AbsenceExcuse.findOneAndUpdate({ _id: req.params.id, status: "pending" }, { $set: { status: "deciding" } }, { new: true });
    if (!ex) return res.status(409).json({ error: "تم اتخاذ قرار على هذا العذر من قبل" });
    try {
        const row = await RecRow.findById(ex.rowId);
        const refund = row ? (row.deducted || 0) : 0;
        const now = new Date();
        const byName = await cyName(req.user.id);
        const upd = { $push: { excusedAbsences: { excuseId: String(ex._id), type: ex.type, absenceAt: row ? row.openedAt : ex.createdAt, approvedAt: now, approvedByName: byName } } };
        if (refund) upd.$inc = { points: refund };
        await Personnel.updateOne({ discord: ex.uid }, upd);
        if (row) await RecRow.updateOne({ _id: row._id }, { $set: { excuseStatus: "accepted", deducted: 0, refunded: refund } });
        await AbsenceExcuse.updateOne({ _id: ex._id }, { $set: { status: "accepted", decidedBy: req.user.id, decidedByName: byName, decidedAt: now, refunded: refund } });
        await logEvent({ action: "قبول عذر غياب", discordId: ex.uid, actorId: req.user.id, actorTag: req.user.username, details: ex.name + (refund ? " — رجعت " + refund + " نقطة" : "") });
        await tellExcuseResult(ex, "✅ تم قبول عذر غيابك عن الاستلام" + (refund ? " ورجعت لك " + refund + " نقطة" : "") + " — تسجّل في ملفك كغياب بعذر.");
        res.json({ ok: true, refunded: refund });
    } catch (e) {
        await AbsenceExcuse.updateOne({ _id: ex._id, status: "deciding" }, { $set: { status: "pending" } });
        res.status(400).json({ error: e.message });
    }
});
app.post("/api/hc/excuses/:id/reject", ensureHighCommand, async (req, res) => {
    if (!mongoose.Types.ObjectId.isValid(req.params.id)) return res.status(404).json({ error: "غير موجود" });
    const reason = String((req.body || {}).reason || "").trim().slice(0, 300);
    if (!reason) return res.status(400).json({ error: "اكتب سبب الرفض" });
    const ex = await AbsenceExcuse.findOneAndUpdate({ _id: req.params.id, status: "pending" }, { $set: { status: "deciding" } }, { new: true });
    if (!ex) return res.status(409).json({ error: "تم اتخاذ قرار على هذا العذر من قبل" });
    try {
        const byName = await cyName(req.user.id);
        await RecRow.updateOne({ _id: ex.rowId }, { $set: { excuseStatus: "rejected" } });
        await AbsenceExcuse.updateOne({ _id: ex._id }, { $set: { status: "rejected", rejectReason: reason, decidedBy: req.user.id, decidedByName: byName, decidedAt: new Date() } });
        await logEvent({ action: "رفض عذر غياب", discordId: ex.uid, actorId: req.user.id, actorTag: req.user.username, details: ex.name + " — " + reason });
        await tellExcuseResult(ex, "❌ تم رفض عذر غيابك عن الاستلام وتثبّت الخصم — السبب: " + reason);
        res.json({ ok: true });
    } catch (e) {
        await AbsenceExcuse.updateOne({ _id: ex._id, status: "deciding" }, { $set: { status: "pending" } });
        res.status(400).json({ error: e.message });
    }
});

// ---------- إزالة الغياب (للمالك فقط) ----------
app.post("/api/owner/att/remove-absence", ensureSeniorAdmin, async (req, res) => {
    if (!isOwnerUid(req.user.id)) return res.status(403).json({ error: "غير مصرح" });
    const b = req.body || {};
    const dayKey = Number(b.dayKey);
    if (!Number.isFinite(dayKey)) return res.status(400).json({ error: "حدد الاستلام" });
    const mode = b.mode === "all" ? "all" : b.mode === "except" ? "except" : null;
    if (!mode) return res.status(400).json({ error: "حدد الكل أو مستثنى" });
    // الكل = ينشال الغياب عن كل الغايبين • مستثنى = الغياب يثبت على الجميع، وينشال بس عن الأشخاص اللي تختارهم
    const picked = new Set(mode === "except" && Array.isArray(b.exceptUids) ? b.exceptUids.map(String) : []);
    const rd = await RecDay.findOne({ dayKey }).lean();
    if (!rd || rd.status === "open") return res.status(409).json({ error: "الاستلام ما انسكّر بعد" });
    const OK = ["none", "pending", "rejected"];
    const rows = await RecRow.find({ dayKey, kind: "absent", excuseStatus: { $in: OK } }, { uid: 1 }).limit(5000).lean();
    if (mode === "except" && !picked.size) return res.status(400).json({ error: "حدد الأشخاص اللي تبي ينشال غيابهم" });
    const targets = mode === "except" ? rows.filter(r => picked.has(String(r.uid))) : rows;
    if (!targets.length) return res.status(400).json({ error: "ما فيه غايبين تنشال عنهم" });
    const now = new Date();
    const byName = await cyName(req.user.id);
    let removed = 0, refundedTotal = 0;
    const done = [];
    for (const t of targets) {
        try {
            const old = await RecRow.findOneAndUpdate(
                { _id: t._id, kind: "absent", excuseStatus: { $in: OK } },
                { $set: { excuseStatus: "removed", deducted: 0, removedAt: now, removedBy: req.user.id, removedByName: byName } },
                { new: false }
            );
            if (!old) continue;
            const ded = old.deducted || 0;
            if (ded) await RecRow.updateOne({ _id: old._id }, { $set: { refunded: ded } });
            if (old.excuseStatus === "pending" && old.excuseId) {
                await AbsenceExcuse.updateOne({ _id: old.excuseId, status: "pending" }, { $set: { status: "rejected", rejectReason: "أُزيل الغياب من المالك", decidedBy: req.user.id, decidedByName: byName, decidedAt: now } });
            }
            const upd = { $push: { removedAbsences: { dayKey, absenceAt: old.openedAt || rd.openedAt, removedAt: now, removedByName: byName, refunded: ded } } };
            if (ded) upd.$inc = { points: ded };
            await Personnel.updateOne({ discord: old.uid }, upd);
            removed++; refundedTotal += ded;
            done.push({ uid: old.uid, name: old.name, ded });
        } catch (e) { console.error("❌ فشل إزالة غياب:", e.message); }
    }
    await logEvent({ action: "إزالة غياب", actorId: req.user.id, actorTag: req.user.username, details: "أُزيل الغياب عن " + removed + " (رجعت " + refundedTotal + " نقطة)" + (mode === "except" ? " • بالاختيار" : " • الكل") });
    (async () => {
        for (const x of done) {
            const text = "🧹 تم إزالة غيابك عن الاستلام" + (x.ded ? " ورجعت لك " + x.ded + " نقطة" : "") + " — وانسجّل في ملفك.";
            await pushNoticeTo(x.uid, text, "auto", "🤖 نظام الاستلام");
            pushUid(x.uid, { title: CONFIG.SITE_NAME, body: text.slice(0, 120), ttl: 86400, tag: "rmabs-" + dayKey }).catch(() => {});
        }
    })();
    res.json({ ok: true, removed, refunded: refundedTotal, skipped: mode === "except" ? Math.max(0, rows.length - targets.length) : 0 });
});

// ---------- مسؤولو الاستلامات + زر فتح استلام ----------
function isReceptionOfficer(uid, settings) { return !!(settings && (settings.receptionOfficers || []).some(m => m.id === uid)); }
app.get("/api/senior/reception", ensureSeniorAdmin, async (req, res) => {
    const s = await getSettings();
    res.json({ list: s.receptionOfficers || [] });
});
app.post("/api/senior/reception/add", ensureSeniorAdmin, async (req, res) => {
    const discordId = String((req.body || {}).discordId || "").trim();
    if (!discordId) return res.status(400).json({ error: "حدد الشخص" });
    const person = await Personnel.findOne({ discord: discordId });
    if (!person || !person.registeredName) return res.status(400).json({ error: "لازم يكون هذا الشخص مسجل بالموقع" });
    const s = await getSettings();
    if (!s.receptionOfficers) s.receptionOfficers = [];
    if (s.receptionOfficers.some(m => m.id === person.discord)) return res.status(400).json({ error: "موجود من قبل" });
    s.receptionOfficers.push({ id: person.discord, name: person.registeredName || person.discordTag });
    s.markModified("receptionOfficers");
    await s.save();
    await logEvent({ action: "إضافة مسؤول استلامات", discordId: person.discord, discordTag: person.discordTag, actorId: req.user.id, actorTag: req.user.username, details: person.registeredName });
    res.json({ ok: true, list: s.receptionOfficers });
});
app.post("/api/senior/reception/remove", ensureSeniorAdmin, async (req, res) => {
    const discordId = String((req.body || {}).discordId || "");
    const s = await getSettings();
    const removed = (s.receptionOfficers || []).find(m => m.id === discordId);
    s.receptionOfficers = (s.receptionOfficers || []).filter(m => m.id !== discordId);
    s.markModified("receptionOfficers");
    await s.save();
    await logEvent({ action: "إزالة مسؤول استلامات", actorId: req.user.id, actorTag: req.user.username, details: (removed && removed.name) || discordId });
    res.json({ ok: true, list: s.receptionOfficers });
});
function riyadhHour() {
    const h = parseInt(new Intl.DateTimeFormat("en-GB", { timeZone: "Asia/Riyadh", hour: "2-digit", hour12: false }).format(new Date()), 10);
    return h % 24;
}
let lastReceptionAt = 0;
app.post("/api/reception/open", ensureAuth, async (req, res) => {
    const settings = await getSettings();
    const isSr = isSeniorAdmin(req.user.id); // الكبار: يفتحون الاستلام بأي وقت وبدون بصمة
    if (!isSr && !isReceptionOfficer(req.user.id, settings)) return res.status(403).json({ error: "هذا الزر لمسؤولي الاستلامات فقط" });
    const att = await getAttState(req.user.id);
    if (!isSr && att.status !== "in") return res.status(403).json({ error: "🖐️ سجّل حضورك بالبصمة أول", needAttendance: true });
    const h = riyadhHour();
    if (!isSr && (h < CONFIG.RECEPTION_START_HOUR || h >= CONFIG.RECEPTION_END_HOUR)) return res.status(400).json({ error: "⏰ مو وقت الاستلام — الاستلام من الساعة 2 العصر إلى 9 الليل" });
    const state = await getReceptionState();
    if (state.open) return res.status(409).json({ error: "الاستلام مفتوح الحين", receptionOpen: state.open });
    const opened = await openReceptionDay(req.user.id, await cyName(req.user.id));
    if (!opened) return res.status(409).json({ error: "الاستلام انفتح قبل شوي" });
    const r = await pushAll({ title: CONFIG.SITE_NAME, body: "استلام الان", ttl: 900, tag: "reception" });
    let discord = false;
    if (botReady) {
        try {
            const ch = await client.channels.fetch(CONFIG.RECEPTION_CHANNEL_ID);
            await ch.send({ content: "استلام @everyone", allowedMentions: { parse: ["everyone"] } });
            discord = true;
        } catch (e) { console.error("❌ فشل إرسال رسالة الاستلام للديسكورد:", e.message); }
    }
    await logEvent({ action: "فتح استلام", actorId: req.user.id, actorTag: req.user.username, details: "إشعار وصل لـ " + r.sent + " جهاز" + (discord ? " + ديسكورد" : "") });
    res.json({ ok: true, sent: r.sent, discord, receptionOpen: { openedAt: opened.openedAt, openedByName: await cyName(req.user.id) } });
});
app.post("/api/reception/close", ensureAuth, async (req, res) => {
    const settings = await getSettings();
    const isSr = isSeniorAdmin(req.user.id);
    if (!isSr && !isReceptionOfficer(req.user.id, settings)) return res.status(403).json({ error: "هذا الزر لمسؤولي الاستلامات فقط" });
    const att = await getAttState(req.user.id);
    if (!isSr && att.status !== "in") return res.status(403).json({ error: "🖐️ سجّل حضورك بالبصمة أول", needAttendance: true });
    const state = await getReceptionState();
    if (!state.open) return res.status(409).json({ error: "الاستلام مو مفتوح الحين", receptionOpen: null });
    let rec = null;
    try { rec = await closeReceptionDay(req.user.id, await cyName(req.user.id)); }
    catch (e) { console.error("❌ فشل إغلاق الاستلام:", e.message); return res.status(500).json({ error: "صار خطأ وقت إغلاق الاستلام" }); }
    if (!rec) return res.status(409).json({ error: "الاستلام انسكّر قبل شوي", receptionOpen: null });
    res.json({ ok: true, rec });
});

// ---------- تردد القطاعات المشتركة (روم صوتي 910..919) ----------
const FreqRoom = mongoose.model("FreqRoom", new mongoose.Schema({
    n: { type: Number, unique: true }, name: String, createdBy: String, createdAt: { type: Date, default: Date.now },
}));
function offIsFreq(n) { return Number.isInteger(n) && n >= 910 && n <= 919; }
function offIsCourt(n) { return Number.isInteger(n) && n >= 950 && n <= 979; }
const FREQ_MAIN = 910;
async function freqExists(n) { return n === FREQ_MAIN || !!(await FreqRoom.exists({ n })); }
app.get("/api/freq/list", ensureAuth, async (req, res) => {
    const extra = await FreqRoom.find({}).sort({ n: 1 }).lean();
    const row = (n, name, main) => ({ n, name, main, count: (offLive.get(n) || new Map()).size });
    res.json({
        list: [row(FREQ_MAIN, "تردد القطاعات المشتركة", true)].concat(extra.map(r => row(r.n, r.name || ("تردد " + (r.n - FREQ_MAIN)), false))),
        max: CONFIG.FREQ_MAX_EXTRA, canManage: isSeniorAdmin(req.user.id),
    });
});
app.post("/api/senior/freq", ensureSeniorAdmin, async (req, res) => {
    const existing = await FreqRoom.find({}).select("n").lean();
    if (existing.length >= CONFIG.FREQ_MAX_EXTRA) return res.status(400).json({ error: "وصلت الحد الأقصى (" + CONFIG.FREQ_MAX_EXTRA + " ترددات إضافية)" });
    const used = new Set(existing.map(r => r.n));
    let n = FREQ_MAIN + 1;
    while (used.has(n) && n < 919) n++;
    const name = String((req.body || {}).name || "").trim().slice(0, 40) || ("تردد " + (n - FREQ_MAIN));
    try { await FreqRoom.create({ n, name, createdBy: req.user.id }); }
    catch (e) { return res.status(409).json({ error: "صار تعارض، جرب مرة ثانية" }); }
    await logEvent({ action: "إنشاء تردد", actorId: req.user.id, actorTag: req.user.username, details: name });
    res.json({ ok: true, n });
});
app.delete("/api/senior/freq/:n", ensureSeniorAdmin, async (req, res) => {
    const n = offParseN(req.params.n);
    if (!n || n === FREQ_MAIN || !offIsFreq(n)) return res.status(400).json({ error: "ما يمديك تحذف هذا التردد" });
    const m = offLive.get(n);
    if (m) for (const uid of Array.from(m.keys())) { offSendTo(uid, { t: "roomdeleted", n }); offRemove(uid, n); }
    offCfg.delete(n); offLive.delete(n); offChat.delete(n);
    await FreqRoom.deleteOne({ n });
    await logEvent({ action: "حذف تردد", actorId: req.user.id, actorTag: req.user.username, details: "تردد " + n });
    res.json({ ok: true });
});

// ---------- المحكمة العسكرية (روم صوتي 950..979) ----------
const CourtCase = mongoose.model("CourtCase", new mongoose.Schema({
    status: { type: String, default: "pending" },        // pending (بانتظار القيادة) | scheduled (موعد محدد) | active | ended | cancelled | rejected
    targetUid: String, targetName: String, reason: { type: String, default: "" },
    startedBy: String, startedByName: String, startedByRole: String,  // mp | senior
    voiceN: { type: Number, default: null },
    muted: { type: [String], default: [] }, kicked: { type: [String], default: [] },
    startedAt: { type: Date, default: Date.now },
    at: { type: Date, default: null }, approvedBy: String, approvedByName: String,
    endedAt: { type: Date, default: null }, endedBy: String, endedByName: String,
    extra: { type: [{ uid: String, name: String }], default: [] },   // متهمين إضافيين مضمومين لنفس المحكمة
    kind: { type: String, default: "court" },                        // court (محكمة) | inv (تحقيق عسكري)
    joinTo: { type: String, default: null },                         // طلب ضم لمحكمة/تحقيق قائم (ينتظر موافقة القيادة)
}));
const courtIcon = c => (c && c.kind === "inv") ? "🔎" : "⚖️";
const courtFor = c => (c && c.kind === "inv") ? "للتحقيق العسكري" : "للمحكمة العسكرية";
const courtWord = c => (c && c.kind === "inv") ? "تحقيق عسكري" : "محكمة عسكرية";
const courtSched = (c, at) => courtIcon(c) + " تم تحديد موعد " + courtWord(c) + " لك: " + courtFmt(at);
const courtKq = k => k === "inv" ? { kind: "inv" } : { kind: { $ne: "inv" } };
function courtTargets(c) { return [{ uid: c.targetUid, name: c.targetName }].concat((c.extra || []).map(e => ({ uid: e.uid, name: e.name }))); }
function courtTargetUids(c) { return courtTargets(c).map(t => t.uid); }
function courtIsTarget(c, uid) { return courtTargetUids(c).includes(uid); }
function courtTargetNames(c) { return courtTargets(c).map(t => t.name).join("، "); }
const soonCourt = new Map();   // targetUid -> { id, at, reason } (موعد محكمة جاي)
const courtSoonOf = uid => soonCourt.get(uid) || null;
function courtFmt(d) {
    try { return new Date(d).toLocaleString("ar-SA", { timeZone: "Asia/Riyadh", weekday: "long", day: "numeric", month: "long", hour: "numeric", minute: "2-digit" }); }
    catch (e) { return String(d); }
}
const underCourt = new Map();   // targetUid -> { id, n, reason, byName, at }
const courtLite = c => ({ id: String(c._id), n: c.voiceN, reason: c.reason || "", byName: c.startedByName || "", at: c.startedAt, kind: c.kind === "inv" ? "inv" : "court" });
async function loadCourt() {
    try {
        // نبني الخرائط من القاعدة (المصدر الحقيقي) ثم نبدلها مرة وحدة، عشان لو انحذفت محكمة من القاعدة تنمسح من الذاكرة
        const nUnder = new Map(), nSoon = new Map(), nKind = new Map();
        (await CourtCase.find({ status: "active" }).lean()).forEach(c => { if (c.voiceN) nKind.set(c.voiceN, c.kind === "inv" ? "inv" : "court"); courtTargetUids(c).forEach(u => nUnder.set(u, courtLite(c))); });
        (await CourtCase.find({ status: "scheduled" }).lean()).forEach(c => courtTargetUids(c).forEach(u => nSoon.set(u, { id: String(c._id), at: c.at, reason: c.reason || "", kind: c.kind === "inv" ? "inv" : "court" })));
        underCourt.clear(); nUnder.forEach((v, k) => underCourt.set(k, v));
        soonCourt.clear(); nSoon.forEach((v, k) => soonCourt.set(k, v));
        courtKindByN.clear(); nKind.forEach((v, k) => courtKindByN.set(k, v));
    } catch (e) { console.error("❌ فشل تحميل المحكمة:", e.message); }
}
function courtCaseOf(uid) { return underCourt.get(uid) || null; }
async function courtRole(uid) {
    if (isSeniorAdmin(uid)) return { staff: true, leader: true, senior: true };
    const settings = await getSettings();
    const mpRole = getMPRole(uid, settings);
    const po = isMPPersonnelOfficer(uid, settings);
    const mem = !!(mpRole || po) || await isMilitaryPoliceMember(uid);
    return { staff: !!mem, leader: !!mpRole, senior: false };
}
function courtPub(c) {
    return { id: String(c._id), kind: c.kind === "inv" ? "inv" : "court", status: c.status, targetUid: c.targetUid, targetName: courtTargetNames(c), targets: courtTargets(c), reason: c.reason || "", by: c.startedBy || "", byName: c.startedByName || "", byRole: c.startedByRole || "", n: c.voiceN, at: c.at || null, startedAt: c.startedAt, endedAt: c.endedAt || null, endedByName: c.endedByName || null, approvedByName: c.approvedByName || null, joinTo: c.joinTo || null };
}
// المشاركين بالمحكمة: المتحقق معه + فاتح التحقيق + اللي داخل الروم الحين
async function courtMembers(c, viewerUid) {
    const ids = new Map();
    courtTargetUids(c).forEach(u => ids.set(u, "target"));
    if (c.startedBy && !ids.has(c.startedBy)) ids.set(c.startedBy, "starter");
    const live = c.status === "active" && c.voiceN ? offLive.get(c.voiceN) : null;
    const inRoom = new Set(live ? Array.from(live.keys()) : []);
    inRoom.forEach(u => { if (!ids.has(u)) ids.set(u, "member"); });
    const out = [];
    for (const [uid, role] of ids) {
        if (isOwnerUid(uid) && !isOwnerUid(viewerUid)) continue;
        out.push({ uid, name: await cyName(uid), role, inRoom: inRoom.has(uid) });
    }
    return out;
}
async function courtPubFull(c, viewerUid) { const o = courtPub(c); o.members = await courtMembers(c, viewerUid); return o; }
async function courtNotifyLeaders(body) {
    try {
        const m = (await getSettings()).mpLeadership || {};
        for (const u of new Set([m.commanderId, m.deputyId].filter(Boolean))) pushUid(u, { title: CONFIG.SITE_NAME, body, tag: "court-req", ttl: 3600 }).catch(() => {});
    } catch (e) {}
}
async function courtAudience() {
    const ids = new Set();
    (await Account.find({ status: "approved", isMP: true }, { uid: 1 }).lean()).forEach(a => ids.add(a.uid));
    const s = await getSettings();
    const m = s.mpLeadership || {};
    [m.commanderId, m.deputyId, m.personnelOfficerId].filter(Boolean).forEach(x => ids.add(x));
    return ids;
}
async function courtPush(targetUid) {
    try {
        const tl = Array.isArray(targetUid) ? targetUid : [targetUid];
        const set = await courtAudience();
        sseBroadcast("court", { t: Date.now() }, c => !!c.uid && (set.has(c.uid) || tl.includes(c.uid) || isSeniorAdmin(c.uid)));
    } catch (e) {}
}
function courtVoiceClose(c) {
    const n = c && c.voiceN;
    if (!n) return;
    const m = offLive.get(n);
    if (m) for (const u of Array.from(m.keys())) { offSendTo(u, { t: "roomdeleted", n }); offRemove(u, n); }
    offCfg.delete(n); offLive.delete(n); offChat.delete(n); courtKindByN.delete(n); offDeaf.delete(n);
}
// أثناء المحكمة: العضو ما يقدر يسوي أي شي إلا يدخل المحكمة
function courtLockGate(req, res, next) {
    if (!req.user) return next();
    if (req.method === "GET" || req.method === "HEAD" || req.method === "OPTIONS") return next();
    if (!underCourt.has(req.user.id)) return next();
    if (req.path.indexOf("/court/") === 0) return next();
    const vr = /^\/officers\/rooms\/(\d+)\//.exec(req.path);
    if (vr && offIsCourt(parseInt(vr[1], 10))) return next();
    const lc = underCourt.get(req.user.id);
    return res.status(403).json({ error: courtIcon(lc) + " أنت مطلوب " + courtFor(lc) + "، ما تقدر تسوي أي إجراء قبل ما تدخل الروم", court: true });
}
app.get("/api/court/state", ensureAuth, async (req, res) => {
    const r = await courtRole(req.user.id);
    const out = { lock: courtCaseOf(req.user.id), mine: courtSoonOf(req.user.id), staff: r.staff, leader: r.leader, senior: r.senior, pending: [], scheduled: [], active: [], recent: [] };
    if (r.staff) {
        const full = list => Promise.all(list.map(c => courtPubFull(c, req.user.id)));
        const kq0 = String(req.query.kind || "");
        const kf = kq0 === "inv" ? courtKq("inv") : (kq0 === "court" ? courtKq("court") : {});
        out.pending = await full(await CourtCase.find(Object.assign({ status: "pending" }, kf)).sort({ at: 1 }).limit(40).lean());
        out.scheduled = await full(await CourtCase.find(Object.assign({ status: "scheduled" }, kf)).sort({ at: 1 }).limit(40).lean());
        out.active = await full(await CourtCase.find(Object.assign({ status: "active" }, kf)).sort({ startedAt: -1 }).limit(40).lean());
        out.recent = (await CourtCase.find(Object.assign({ status: { $in: ["ended", "cancelled", "rejected"] } }, kf)).sort({ endedAt: -1 }).limit(30).lean()).map(courtPub);
    }
    res.json(out);
});
// فتح تحقيق: لازم يوم وساعة ودقيقة. القيادة والكبار ينحدد الموعد على طول، وعضو الشرطة العسكرية العادي يروح الطلب للقيادة
app.post("/api/court/start", ensureAuth, async (req, res) => {
    const r = await courtRole(req.user.id);
    if (!r.staff) return res.status(403).json({ error: "المحكمة العسكرية للشرطة العسكرية وكبار المسؤولين فقط" });
    const b = req.body || {};
    const targetUid = String(b.targetUid || "");
    const reason = String(b.reason || "").trim().slice(0, 300);
    const kind = b.kind === "inv" ? "inv" : "court";
    if (!targetUid || targetUid === req.user.id) return res.status(400).json({ error: "ما تقدر تفتح تحقيق على نفسك" });
    const ta = await Account.findOne({ uid: targetUid, status: "approved" }, { isSenior: 1, isOwner: 1, tempSenior: 1 }).lean();
    if (!ta) return res.status(404).json({ error: "هذا العضو غير موجود" });
    if (isSeniorAdmin(targetUid) || isOwnerUid(targetUid) || ta.isSenior || ta.isOwner || ta.tempSenior) return res.status(403).json({ error: "ما يمديك تفتح تحقيق على هذا الشخص" });
    const startNow = kind === "inv" && !!b.now;
    const at = startNow ? new Date() : offBuildDate(b.date, b.hour, b.minute);
    if (!at) return res.status(400).json({ error: "حدد اليوم والساعة والدقيقة بشكل صحيح" });
    if (at.getTime() < Date.now() - 5 * 60 * 1000) return res.status(400).json({ error: "الموعد لازم يكون من الحين وطالع" });
    if (await CourtCase.exists({ $or: [{ targetUid }, { "extra.uid": targetUid }], status: { $in: ["pending", "scheduled", "active"] } })) return res.status(409).json({ error: "هذا العضو عليه " + (kind === "inv" ? "تحقيق" : "محكمة") + " أو طلب حالياً" });
    {
        const dir = !!(r.senior || r.leader);
        const mode = b.mode === "join" ? "join" : (b.mode === "separate" ? "separate" : "");
        const openCases = await CourtCase.find({ status: { $in: ["pending", "scheduled", "active"] } }).sort({ startedAt: -1 }).limit(10).lean();
        const joinable = openCases.filter(x => courtTargets(x).length < 5 && ((x.kind === "inv") === (kind === "inv")));
        if (!mode && joinable.length) {
            return res.status(409).json({
                error: "فيه " + (kind === "inv" ? "تحقيق قائم، اختر: ضمه له أو تحقيق منفصل" : "محكمة قائمة، اختر: ضمه لها أو محكمة منفصلة"), choose: true, kind, direct: dir,
                cases: joinable.map(x => ({ id: String(x._id), kind: x.kind === "inv" ? "inv" : "court", status: x.status, targetName: courtTargetNames(x), at: x.at, n: x.voiceN || null, startedAt: x.startedAt })),
            });
        }
        if (mode === "join") {
            const jc = joinable.find(x => String(x._id) === String(b.joinId));
            if (!jc) return res.status(404).json({ error: (kind === "inv" ? "هذا التحقيق" : "هذي المحكمة") + " ما يقبل الضم حالياً" });
            const jName = await cyName(targetUid), byN = await cyActor(req);
            if (!dir && jc.status !== "pending") {
                // عضو شرطة عسكرية عادي: ضم لتحقيق/محكمة مجدولة أو جارية يروح كطلب للقيادة (نفس نظام المحكمة)
                const rq = await CourtCase.create({ status: "pending", targetUid, targetName: jName, reason, startedBy: req.user.id, startedByName: byN, startedByRole: "mp", at: jc.at || new Date(), kind, joinTo: String(jc._id) });
                courtNotifyLeaders(courtIcon(rq) + " " + byN + " طلب ضم " + jName + " إلى " + courtWord(rq) + " " + (jc.status === "active" ? "جاري" : "مجدول") + " مع " + courtTargetNames(jc));
                await logEvent({ action: "طلب ضم لـ" + courtWord(rq), discordId: targetUid, actorId: req.user.id, actorTag: byN + " (الشرطة العسكرية)", details: jName + " ← " + courtTargetNames(jc) });
                courtPush(targetUid);
                courtTick();
                return res.json({ ok: true, id: String(rq._id), status: "pending", kind, requested: true });
            }
            const upd = await CourtCase.findOneAndUpdate({ _id: jc._id, status: jc.status }, { $push: { extra: { uid: targetUid, name: jName } } }, { new: true });
            if (!upd) return res.status(409).json({ error: (kind === "inv" ? "التحقيق" : "المحكمة") + " تغيّرت حالته، حاول مرة ثانية" });
            if (upd.status === "active") {
                underCourt.set(targetUid, courtLite(upd));
                pushUid(targetUid, { title: CONFIG.SITE_NAME, body: courtIcon(upd) + " أنت مطلوب " + courtFor(upd) + "، ادخل الموقع الحين", tag: "court", ttl: 1800 }).catch(() => {});
            } else if (upd.status === "scheduled") {
                soonCourt.set(targetUid, { id: String(upd._id), at: upd.at, reason: upd.reason || "", kind: upd.kind === "inv" ? "inv" : "court" });
                pushUid(targetUid, { title: CONFIG.SITE_NAME, body: courtSched(upd, upd.at), tag: "court-soon", ttl: 86400 }).catch(() => {});
            } else {
                courtNotifyLeaders(courtIcon(upd) + " " + byN + " ضم " + jName + " لطلب " + courtWord(upd) + " مع " + upd.targetName);
            }
            sseBroadcast("courtlock", { t: Date.now() }, cl => cl.uid === targetUid);
            await logEvent({ action: "ضم عضو لـ" + courtWord(upd), discordId: targetUid, actorId: req.user.id, actorTag: byN, details: jName + " ← " + courtWord(upd) + " " + courtTargetNames(upd) });
            courtPush(courtTargetUids(upd));
            courtTick();
            return res.json({ ok: true, id: String(upd._id), status: upd.status, joined: true });
        }
    }
    const direct = r.senior || r.leader;
    const byName = await cyActor(req), targetName = await cyName(targetUid);
    const c = await CourtCase.create({ status: direct ? "scheduled" : "pending", targetUid, targetName, reason, startedBy: req.user.id, startedByName: byName, startedByRole: r.senior ? "senior" : (r.leader ? "leader" : "mp"), at, kind });
    if (direct) {
        soonCourt.set(targetUid, { id: String(c._id), at, reason, kind });
        if (!startNow) pushUid(targetUid, { title: CONFIG.SITE_NAME, body: courtSched(c, at), tag: "court-soon", ttl: 86400 }).catch(() => {});
        sseBroadcast("courtlock", { t: Date.now() }, cl => cl.uid === targetUid);
    } else {
        courtNotifyLeaders(courtIcon(c) + " طلب " + courtWord(c) + " جديد من " + byName + " على " + targetName + " — الموعد: " + (startNow ? "الحين" : courtFmt(at)));
    }
    await logEvent({ action: (kind === "inv" ? (direct ? "فتح تحقيق عسكري" : "طلب تحقيق عسكري") : (direct ? "تحديد موعد محكمة عسكرية" : "طلب تحقيق بالمحكمة العسكرية")), discordId: targetUid, actorId: req.user.id, actorTag: byName + (r.senior ? " (كبار المسؤولين)" : r.leader ? " (قيادة الشرطة العسكرية)" : " (الشرطة العسكرية)"), details: targetName + " — " + courtFmt(at) + (reason ? " — " + reason : "") });
    courtPush(targetUid);
    courtTick();
    res.json({ ok: true, id: String(c._id), status: c.status, kind });
});
async function courtAccess(req, res, needLead) {
    if (!mongoose.Types.ObjectId.isValid(req.params.id)) { res.status(400).json({ error: "رقم غير صحيح" }); return null; }
    const c = await CourtCase.findById(req.params.id);
    if (!c) { res.status(404).json({ error: "غير موجود" }); return null; }
    const r = await courtRole(req.user.id);
    const isT = courtIsTarget(c, req.user.id);
    if (!isT && !r.staff) { res.status(403).json({ error: "ليست لديك صلاحية" }); return null; }
    if (needLead && (isT || !(r.leader || c.startedBy === req.user.id))) { res.status(403).json({ error: "هذا الإجراء لقيادة الشرطة العسكرية أو اللي فتح التحقيق أو الكبار" }); return null; }
    return { c, r, isT };
}
app.get("/api/court/admin/records", ensureSeniorAdmin, async (req, res) => {
    const kq1 = String(req.query.kind || "");
    const list = await CourtCase.find(Object.assign({ status: { $in: ["active", "ended", "cancelled"] }, voiceN: { $ne: null } }, kq1 === "inv" ? courtKq("inv") : (kq1 === "court" ? courtKq("court") : {}))).sort({ startedAt: -1 }).limit(60).lean();
    const since = list.length ? new Date(new Date(list[list.length - 1].startedAt).getTime() - 3 * 60000) : new Date();
    const recs = await OfficerRec.find({ n: { $gte: 950, $lte: 979 }, startedAt: { $gte: since }, chunks: { $gt: 0 } }).select("n startedAt").lean();
    res.json({
        list: list.map(c => {
            const lo = new Date(c.startedAt).getTime() - 120000;
            const hi = (c.endedAt ? new Date(c.endedAt).getTime() : Date.now()) + 120000;
            const rc = recs.filter(r => r.n === c.voiceN && new Date(r.startedAt).getTime() >= lo && new Date(r.startedAt).getTime() <= hi).length;
            return { id: String(c._id), status: c.status, targetName: courtTargetNames(c), reason: c.reason || "", byName: c.startedByName || "", startedAt: c.startedAt, endedAt: c.endedAt || null, endedByName: c.endedByName || null, n: c.voiceN, recs: rc };
        }),
    });
});
app.get("/api/court/admin/:id/session", ensureSeniorAdmin, async (req, res) => {
    if (!mongoose.Types.ObjectId.isValid(req.params.id)) return res.status(400).json({ error: "رقم غير صحيح" });
    const c = await CourtCase.findById(req.params.id).lean();
    if (!c || !c.voiceN) return res.status(404).json({ error: "هذي المحكمة ما بدأت أو ما لها سجل" });
    const startMs = new Date(c.startedAt).getTime();
    const lo = new Date(startMs - 120000);
    const hi = c.endedAt ? new Date(new Date(c.endedAt).getTime() + 120000) : new Date();
    const logs = await OfficerRoomLog.find({ n: c.voiceN, at: { $gte: lo, $lte: hi } }).sort({ at: 1 }).limit(2000).lean();
    const stays = [], open = new Map();
    for (const l of logs) {
        const t = new Date(l.at).getTime();
        if (l.action === "join") {
            const prev = open.get(l.uid); if (prev) { prev.lost = true; open.delete(l.uid); }
            const st = { uid: l.uid, name: l.name, isSenior: !!l.isSenior || l.role === "senior", role: l.role, start: t, end: null, lost: false, ongoing: false };
            open.set(l.uid, st); stays.push(st);
        } else if (l.action === "leave") {
            const st = open.get(l.uid); if (st) { st.end = t; open.delete(l.uid); }
        }
    }
    const live = c.status === "active";
    const liveNow = live ? (offLive.get(c.voiceN) || new Map()) : new Map();
    for (const st of open.values()) { if (live && liveNow.has(st.uid)) st.ongoing = true; else st.lost = true; }
    const recs = await OfficerRec.find({ n: c.voiceN, startedAt: { $gte: lo, $lte: hi }, chunks: { $gt: 0 } }).sort({ startedAt: 1 }).select("sid n name mime startedAt endedAt lastAt speech").lean();
    const lastEnd = stays.reduce((m, x) => Math.max(m, x.end || 0), 0);
    const end = c.endedAt ? new Date(c.endedAt).getTime() : (live ? null : (lastEnd || startMs));
    res.json({ session: {
        room: c.voiceN, title: (c.kind === "inv" ? "تحقيق " : "محكمة ") + courtTargetNames(c), training: false, start: startMs, end, live, stays,
        recs: recs.map(r => ({ sid: r.sid, name: r.name, mime: r.mime, start: new Date(r.startedAt).getTime(), end: r.endedAt ? new Date(r.endedAt).getTime() : (r.lastAt ? new Date(r.lastAt).getTime() : null), speech: r.speech || [] })),
    } });
});
app.post("/api/court/:id/end", ensureAuth, async (req, res) => {
    const x = await courtAccess(req, res, true); if (!x) return;
    const st = x.c.status;
    if (!["active", "scheduled", "pending"].includes(st)) return res.status(409).json({ error: (x.c.kind === "inv" ? "التحقيق منتهي" : "المحكمة منتهية") + " مسبقاً" });
    const name = await cyActor(req);
    const c = await CourtCase.findOneAndUpdate({ _id: x.c._id, status: st }, { $set: { status: st === "active" ? "ended" : "cancelled", endedAt: new Date(), endedBy: req.user.id, endedByName: name } }, { new: true });
    if (!c) return res.status(409).json({ error: "المحكمة انتهت أو انلغت مسبقاً" });
    if (st === "active") { courtTargetUids(c).forEach(u => underCourt.delete(u)); courtVoiceClose(c); }
    else {
        courtTargetUids(c).forEach(u => {
            soonCourt.delete(u);
            if (st === "scheduled") pushUid(u, { title: CONFIG.SITE_NAME, body: courtIcon(c) + " تم إلغاء موعد " + courtWord(c), tag: "court-soon", ttl: 86400 }).catch(() => {});
        });
    }
    await logEvent({ action: st === "active" ? "إنهاء " + courtWord(c) : "إلغاء " + courtWord(c), discordId: c.targetUid, actorId: req.user.id, actorTag: name, details: c.targetName });
    courtPush(courtTargetUids(c));
    sseBroadcast("courtlock", { t: Date.now() }, cl => courtIsTarget(c, cl.uid));
    res.json({ ok: true });
});
// قيادة الشرطة العسكرية: قبول / رفض طلب التحقيق
app.post("/api/court/:id/approve", ensureAuth, async (req, res) => {
    const x = await courtAccess(req, res, false); if (!x) return;
    if (x.isT || !x.r.leader) return res.status(403).json({ error: "قبول الطلبات لقيادة الشرطة العسكرية فقط" });
    if (x.c.status !== "pending") return res.status(409).json({ error: "هذا الطلب انبت فيه مسبقاً" });
    const b = req.body || {};
    const inv = x.c.kind === "inv";
    let joinPick = b.joinId;
    // القيادة تقدر تحدد/تعدل الموعد وقت القبول
    let at = x.c.at || new Date();
    if (inv && b.now) at = new Date();
    else if (b.date) {
        const d = offBuildDate(b.date, b.hour, b.minute);
        if (!d) return res.status(400).json({ error: "حدد اليوم والساعة والدقيقة بشكل صحيح" });
        if (d.getTime() < Date.now() - 5 * 60 * 1000) return res.status(400).json({ error: "الموعد لازم يكون من الحين وطالع" });
        at = d;
    }
    const name = await cyActor(req);
    let mode = b.mode === "join" ? "join" : (b.mode === "separate" ? "separate" : "");
    const mine = courtTargets(x.c);
    // بعد القبول وتحديد الموعد: لو فيه محكمة/تحقيق مجدول أو جاري يطلع له خيار الضم أو الفصل
    const others = await CourtCase.find(Object.assign({ status: { $in: ["scheduled", "active"] }, _id: { $ne: x.c._id } }, courtKq(x.c.kind))).sort({ startedAt: -1 }).limit(10).lean();
    const joinable = others.filter(o => courtTargets(o).length + mine.length <= 5);
    // طلب ضم لتحقيق/محكمة قائمة: عند القبول ينضم له مباشرة (لو لسا يقبل الضم)
    if (!mode && x.c.joinTo && joinable.some(o => String(o._id) === String(x.c.joinTo))) { mode = "join"; joinPick = x.c.joinTo; }
    if (!mode && joinable.length) {
        return res.status(409).json({
            error: "فيه " + (inv ? "تحقيق" : "محكمة") + " قائمة، اختر: ضمه لها أو منفصل", choose: true,
            cases: joinable.map(o => ({ id: String(o._id), kind: o.kind === "inv" ? "inv" : "court", status: o.status, targetName: courtTargetNames(o), at: o.at, n: o.voiceN || null, startedAt: o.startedAt })),
        });
    }
    if (mode === "join") {
        const jc = joinable.find(o => String(o._id) === String(joinPick));
        if (!jc) return res.status(404).json({ error: (inv ? "هذا التحقيق" : "هذي المحكمة") + " ما يقبل الضم حالياً" });
        const upd = await CourtCase.findOneAndUpdate({ _id: jc._id, status: jc.status }, { $push: { extra: { $each: mine.map(m => ({ uid: m.uid, name: m.name })) } } }, { new: true });
        if (!upd) return res.status(409).json({ error: "المحكمة تغيّرت حالتها، حاول مرة ثانية" });
        const mg = await CourtCase.findOneAndUpdate({ _id: x.c._id, status: "pending" }, { $set: { status: "merged", approvedBy: req.user.id, approvedByName: name, endedAt: new Date(), endedBy: req.user.id, endedByName: name } });
        if (!mg) { await CourtCase.updateOne({ _id: upd._id }, { $pull: { extra: { uid: { $in: mine.map(m => m.uid) } } } }); return res.status(409).json({ error: "هذا الطلب انبت فيه مسبقاً" }); }
        mine.forEach(m => {
            if (upd.status === "active") {
                underCourt.set(m.uid, courtLite(upd));
                pushUid(m.uid, { title: CONFIG.SITE_NAME, body: courtIcon(upd) + " أنت مطلوب " + courtFor(upd) + "، ادخل الموقع الحين", tag: "court", ttl: 1800 }).catch(() => {});
            } else {
                soonCourt.set(m.uid, { id: String(upd._id), at: upd.at, reason: upd.reason || "", kind: upd.kind === "inv" ? "inv" : "court" });
                pushUid(m.uid, { title: CONFIG.SITE_NAME, body: courtSched(upd, upd.at), tag: "court-soon", ttl: 86400 }).catch(() => {});
            }
        });
        await logEvent({ action: "قبول طلب وضمه لـ" + courtWord(upd), discordId: x.c.targetUid, actorId: req.user.id, actorTag: name + " (قيادة الشرطة العسكرية)", details: courtTargetNames(x.c) + " ← " + courtTargetNames(upd) });
        if (x.c.startedBy) pushUid(x.c.startedBy, { title: CONFIG.SITE_NAME, body: "✅ وافقت القيادة وانضم " + x.c.targetName + " لـ" + courtWord(upd) + " قائم", tag: "court-req", ttl: 86400 }).catch(() => {});
        sseBroadcast("courtlock", { t: Date.now() }, cl => mine.some(m => m.uid === cl.uid));
        courtPush(courtTargetUids(upd));
        courtTick();
        return res.json({ ok: true, joined: true });
    }
    const c = await CourtCase.findOneAndUpdate({ _id: x.c._id, status: "pending" }, { $set: { status: "scheduled", at, approvedBy: req.user.id, approvedByName: name } }, { new: true });
    if (!c) return res.status(409).json({ error: "هذا الطلب انبت فيه مسبقاً" });
    courtTargetUids(c).forEach(u => soonCourt.set(u, { id: String(c._id), at: c.at, reason: c.reason || "", kind: c.kind === "inv" ? "inv" : "court" }));
    await logEvent({ action: inv ? "قبول طلب تحقيق عسكري" : "قبول طلب تحقيق بالمحكمة العسكرية", discordId: c.targetUid, actorId: req.user.id, actorTag: name + " (قيادة الشرطة العسكرية)", details: c.targetName + " — " + courtFmt(c.at) });
    if (!(inv && b.now)) courtTargetUids(c).forEach(u => pushUid(u, { title: CONFIG.SITE_NAME, body: courtSched(c, c.at), tag: "court-soon", ttl: 86400 }).catch(() => {}));
    if (c.startedBy) pushUid(c.startedBy, { title: CONFIG.SITE_NAME, body: "✅ وافقت القيادة على طلب " + courtWord(c) + " مع " + c.targetName, tag: "court-req", ttl: 86400 }).catch(() => {});
    sseBroadcast("courtlock", { t: Date.now() }, cl => courtIsTarget(c, cl.uid));
    courtPush(courtTargetUids(c));
    courtTick();
    res.json({ ok: true });
});
