                return '<div class="sp-row" style="cursor:default;"><div class="t1"><span>#' + r.no + ' — ' + spEsc(r.name || '-') + '</span><span>' + '★'.repeat(r.stars) + '</span></div><div class="t2">' + spEsc(r.comment) + '</div><div class="t2">الإداري: ' + spEsc(r.adminName || '-') + '</div></div>';
