    __pollRunning = false;
    if (deep) {
        try { if (typeof spReconnect === 'function') spReconnect(); } catch (e) {}
        try { if (ME && !ME.blocked && !(window.CY && CY.frozen) && !(window.UA && UA.frozen)) startPolling(); } catch (e) {}
    }
