const PENALTY_TYPE_LABELS = { points: 'خصم نقاط', resetPoints: 'تصفير النقاط', demote: 'تنزيل رتبة', demoteToFirst: 'تنزيل لأول رتبة', suspend: 'إيقاف مؤقت', combo: 'عقوبة مركّبة', dismiss: 'فصل نهائي' };
