        if (silent && sig === OFF.sig) return;
        OFF.sig = sig; OFF.my = d.app; OFF.locked = !!d.locked; OFF.rankBlocked = !!d.rankBlocked;
        if (document.getElementById('off-root')) offPaintApplicant();
